function note(body, id) {
  return `${body}\n[Sources]\n- ${U[id][0]}\n- ${U[id][1]}\n[/Sources]`;
}

function autoNotes(p) {
  const s = p.slides;
  return {
    positioning: note(`【研究问题与定位】${s.positioning.visibleText} 本页需要把论文的主张放回其数据与任务边界中理解。作者给出的定位包括：${s.positioning.sections.join('；')}。讲解时应先说明论文真正解决的瓶颈，再区分“输入接口、预训练目标、模型规模”三种不同贡献，避免把任何使用 Transformer 的工作都称为同一种基础模型。最后指出该主张迁移到腕部/前臂 sEMG 时需要重新验证的域变化，包括受试者、日期、腕带旋转、沿前臂位移和设备差异。`, p.id),
    overviewFigure: note(`【原图逐项解读】${s.overviewFigure.visibleText} 图中的编号应按数据流顺序讲：${s.overviewFigure.numberedExplanations.join('；')}。需要特别指出哪些对象是连续 patch embedding，哪些是真正的离散 token；只有出现向量量化与有限 codebook 时，token ID 才是离散词汇。对资源型论文，则把设备、参与者、任务、标签和切分视为数据流中的关键节点。读图结束后，应回到该图能证明什么、不能证明什么，而不是把架构图本身当作性能证据。`, p.id),
    mechanism: note(`【机制与损失】${s.mechanism.visibleText} 具体模块依次为：${s.mechanism.modules.join('；')}。核心训练信号是：${s.mechanism.lossExplanation}。讲解时要明确重建、对比、教师—学生对齐、离散 token 分类和 flow matching（流匹配）对应不同信息瓶颈；它们可能互补，却不能互相替代。迁移到 1 kHz sEMG 时，应检查预处理是否保留快速运动相关的相位、爆发边界、幅度和频谱细节，并把任何强增强与实际佩戴扰动建立物理对应。`, p.id),
    evidence: note(`【实验、消融与边界】${s.evidence.visibleText} 数据与协议包括：${s.evidence.datasets.join('；')}。论文采用的指标或主要结论包括：${s.evidence.metrics.join('；')}。关键消融为：${s.evidence.ablations.join('；')}。限制是：${s.evidence.limits.join('；')}。报告结果时不能混合不同任务的指标，也不能把随机窗口划分的高分解释为跨受试者泛化。若来源没有统一报告某个规模或指标，应保留这种不确定性，而不是补猜数值。`, p.id),
    transfer: note(`【对 sEMG 基座的可执行迁移】${s.transfer.visibleText} 可借鉴的创新是：${s.transfer.innovations.join('；')}。建议保留：${s.transfer.borrow.join('；')}。需要避免：${s.transfer.avoid.join('；')}。可直接实施的实验为：${s.transfer.experiments.join('；')}。评测必须让离散手势与连续手指/腕部运动同等重要，并以 held-out subject、day、rotation、displacement 和 device 为主轴；只有在这些条件下，预训练增益才可被解释为运动语义迁移，而非个体、会话或硬件捷径。`, p.id)
  };
}

const baseRecords = [
  {
    id:'bendr', title:'BENDR', fullTitle:'Using Transformers and a Contrastive Self-Supervised Learning Task to Learn From Massive Amounts of EEG Data', venue:'Frontiers in Human Neuroscience 2021', status:'peer-reviewed', source:U.bendr[0], pdfSource:U.bendr[1],
    slides:{
      positioning:{title:'BENDR：从原始 EEG 到可迁移连续潜表示',sections:['问题：不同硬件、通道、受试者与任务使监督 EEG 模型难以迁移','定位：以 TUEG 大规模临床 EEG 做任务无关预训练，再迁移到未见范式','创新：把 wav2vec 2.0 式卷积潜表示、上下文 Transformer 与遮蔽位置对比预测移植到多通道 EEG'],visibleText:'BENDR 不把脑电先变成离散词表，而是先用卷积前端把 256 Hz 原始波形压成约 2.67 Hz 的连续潜序列，再让 Transformer 在遮蔽上下文中辨认正确潜向量。预训练采用 TUEG 1.1/1.2，覆盖一万余人、不同年龄、会话和硬件；下游包含运动想象、错误相关电位、P300 与睡眠分期。它回答的不是单一任务精度，而是“跨数据集的原始波形特征能否复用”。对腕部/前臂 sEMG 的直接启示是：先验证连续潜表示与上下文预测，未必需要一开始就引入 codebook（码本）。'},
      overviewFigure:{title:'Figure 1：卷积潜表示—遮蔽—上下文对比预测',numberedExplanations:['① 左侧多通道 raw EEG 直接进入卷积编码器；论文统一到 20 个输入通道，其中 19 个为 10–20 电极、1 个保留相对幅度信息。','② 六个卷积块以步幅降采样，总压缩因子为 96；每个时间位置得到 512 维连续 BENDR 向量，而非离散 token。','③ 连续的潜位置按跨度遮蔽：起点概率 0.065、遮蔽长度 10，遮蔽向量由训练学习。','④ 八层、八头 Transformer 聚合长程上下文，输出遮蔽位置的上下文化表示。','⑤ 训练把正确的未遮蔽潜向量作为目标，并与同一序列均匀采样的 20 个干扰向量做余弦相似度对比。'],visibleText:'图中最重要的分界是：卷积输出 b_t 是连续目标，Transformer 输出 c_t 是根据可见上下文推断出的表示。BENDR 明确没有沿用 wav2vec 2.0 的向量量化，因此这里的 token 只是序列位置上的潜向量，不存在固定 codebook。负样本来自同一条序列，减少跨记录幅度或设备差异造成的捷径；但也意味着模型主要学习局部时序可辨识性。迁移到 1 kHz sEMG 时，可将短时高频形态先卷积降采样，再用上下文网络恢复被遮蔽的肌肉激活片段，同时谨慎控制压缩率，避免抹掉快速手指运动。'},
      mechanism:{title:'机制：连续目标的对比式掩蔽预测',modules:['预处理：各序列线性缩放至 [-1,1]，统一至 256 Hz；通道映射到精简 Deep1010，缺失通道补零','局部编码：六层 Conv1D + GroupNorm + GELU，将 375 ms 左右感受野映射为 512 维连续潜表示','上下文骨干：位置卷积后进入 8 层 Transformer；下游以首位固定 token 的输出做序列分类','目标：遮蔽位置 c_t 与真实 b_t 的余弦相似度，经温度 0.1 的 InfoNCE 区分 20 个同序列负样本','正则：BENDR 激活均方值加入损失，约束潜表示幅度'],lossExplanation:'核心损失是遮蔽位置的对比分类，而不是波形均方重建，也不是 codebook token 交叉熵。正确 b_t 为正样本，同一序列其他位置为负样本；损失迫使 Transformer 利用上下文恢复“哪个连续潜向量属于当前位置”。',visibleText:'BENDR 的设计把“局部生理滤波器”和“全局任务上下文”分成两个阶段。预训练以 60 秒片段学习，微调既比较完整 BENDR，也比较冻结卷积前端加线性头。模型没有教师网络、没有向量量化，也没有跨样本增强视图对齐。对 sEMG 而言，这一区分很关键：若目标是离散手势和连续运动同等重要，连续潜目标更能保留幅度、速度和转折信息；可增加通道旋转增强和跨日正对，但不应把不同动作阶段误当负样本。'},
      evidence:{title:'证据：跨范式迁移有效，但不是所有任务都由完整模型获胜',datasets:['预训练：TUEG v1.1/v1.2，约 1.5 TB EDF，超过 10,000 人；60 秒片段','下游：MMI 105 人、BCIC 9 人、ERN 26+10 人、P300 9 人、睡眠分期 83 人'],metrics:['MMI/睡眠使用平衡准确率，BCIC 使用准确率，ERN/P300 使用 AUROC','论文 Table 2 的最佳平均结果中，MMI 86.7 BAC、BCIC 42.6% accuracy、ERN 0.65 AUROC、睡眠 0.72 BAC 多由线性配置取得；P300 的 0.72 AUROC 由完整 BENDR 配置取得'],ablations:['比较随机初始化、预训练卷积前端、预训练完整上下文模型及冻结/微调设置','序列长度实验显示更长预训练上下文总体有利，但短下游片段与位置卷积存在匹配问题'],limits:['通道被强制映射到固定 20 通道，通用性依赖预处理','同序列负样本可能把相邻生理阶段当作负类；完整 Transformer 并非每个下游最优'],visibleText:'实验证据支持“预训练卷积特征可复用”，但不支持“越完整的预训练模型在所有任务上越好”。多项任务的最佳结果来自预训练编码器配合较浅下游模型，说明上下文层可能吸收了 TUEG 特有的时间结构。论文采用跨受试者折分，ERN 还有 10 名独立测试受试者，是可取的泛化评测；然而它没有专门验证跨日佩戴位移、旋转或跨设备。对 sEMG 项目应把这些域变化设为一等测试轴，而不是只做随机窗划分。'},
      transfer:{title:'迁移到 1 kHz 腕部/前臂 sEMG：先做连续基线',innovations:['连续潜表示作为预测目标，避免码本过早离散化','局部卷积与长程 Transformer 分工明确','同记录负样本降低设备域捷径'],borrow:['以 20–40 ms 卷积感受野保留运动单位叠加形态，再下采样到动作级 token','对 0.5–4 秒上下文做跨度掩蔽，联合离散手势分类与连续关节轨迹回归微调'],avoid:['不要复制 96 倍压缩；1 kHz sEMG 的快速变化需用频谱与下游轨迹共同选压缩率','不要只从同一动作序列取负样本，否则连续运动相邻阶段会被错误推远'],experiments:['E1：连续 BENDR 目标 vs 波形掩蔽重建 vs 二者联合，报告手势 macro-F1 与连续角度 MAE/相关系数','E2：压缩因子 16/32/64 与遮蔽跨度 20/50/100 ms 网格消融，分析快速指动损失','E3：严格 held-out subject、held-out day、腕带旋转/位移测试，并加入跨设备重采样','E4：负样本仅同记录、跨受试者同动作、跨动作三种策略对比，检查动作语义与个体捷径'],visibleText:'推荐把 BENDR 作为 sEMG 基座的“最小可信连续预训练”对照：原始多通道 sEMG 经短卷积形成连续 token，掩蔽后由 Transformer 预测正确潜向量。主实验必须同时报告离散手势与连续手指/腕部轨迹，不能用一个任务代替另一个。最关键的新增条件是腕带旋转、沿前臂位移、跨日接触阻抗和跨设备采样差异；如果连续目标在这些条件下优于 codebook 方案，就说明幅度与相位细节对通用运动交互仍然必要。'}
    },
    notes:{
      positioning:note('BENDR 的问题设定来自 EEG 的强域偏移：硬件、通道布局、受试者和实验范式都在变，而标注数据通常很小。作者选择 TUEG 作为预训练来源，因为它包含一万余人的临床记录、跨月会话和多种采集条件；这比在某一个 BCI 任务内做自监督更接近基础模型。要注意论文发表于 2021 年，术语“foundation model”尚未普及，但其跨数据预训练—未见任务迁移范式已具雏形。作者并未声称一个大 Transformer 解决所有任务，反而在结果中显示浅层迁移有时更稳。对于 sEMG，正确的继承是跨人、跨日、跨佩戴条件学习局部肌肉形态，而不是照抄 EEG 的固定电极映射。', 'bendr'),
      overviewFigure:note('Figure 1 从左到右展示原始多通道 EEG、卷积潜表示 BENDR、跨度遮蔽、Transformer 上下文表示与对比损失。卷积总步幅 96，把 256 Hz 变为约 2.67 Hz，每个潜向量 512 维。遮蔽不是删除单点，而是从概率 0.065 的起点开始覆盖 10 个连续潜位置；Transformer 必须借助前后文恢复位置 t。目标 b_t 保持连续，20 个干扰项从同一序列均匀抽取，温度为 0.1。图中没有 tokenizer 或 codebook，这一点必须与 LaBraM 的离散神经 token 区分。对于 1 kHz sEMG，应先通过下游运动学保真度决定降采样倍数，不能把 EEG 的 375 ms 特征窗直接搬来。', 'bendr'),
      mechanism:note('原始序列先被缩放到 [-1,1]，并通过 Deep1010 映射到 19 个标准 EEG 通道，另加一个常数通道保留被归一化抹掉的相对幅度；缺失通道置零。六个 Conv1D 块均为卷积、GroupNorm、GELU，之后加位置卷积并进入 8 层 8 头 Transformer。损失是遮蔽位置上下文输出 c_t 对正确连续潜向量 b_t 的 InfoNCE 式分类，再加潜激活均方正则。它既不是原始波形 MSE，也不是教师—学生特征对齐，更不是离散 token 预测。该机制适合建立 sEMG 的强基线，但同序列负样本会把连续动作的相邻阶段推开，因此要设计阶段感知的采样策略。', 'bendr'),
      evidence:note('预训练使用 TUEG v1.1/1.2 的约 1.5 TB EDF，并按 60 秒片段训练；下游覆盖 MMI、BCIC、ERN、P300 与睡眠分期。Table 2 报告的最佳平均结果分别使用 BAC、accuracy 或 AUROC，不能横向当作统一分数。值得重视的是，MMI、BCIC、ERN 和睡眠的最佳配置并非都采用完整预训练 Transformer，P300 才由完整 BENDR 配置取得最佳值。这提示预训练上下文存在任务错配，而卷积局部表征可能更通用。论文采用留出受试者折分，但没有腕带式研究所需的跨日、旋转、位移和跨设备测试；因此迁移结论必须在 sEMG 新协议上重新验证。', 'bendr'),
      transfer:note('在腕部/前臂 sEMG 中，建议先实现连续潜目标：每通道以 20–40 ms 局部卷积形成 token，跨通道融合后在 0.5–4 秒动作上下文中做跨度掩蔽。下游用同一个编码器连接两类头：离散手势用 macro-F1/平衡准确率，连续手指和腕部运动用 MAE、相关系数和时延。至少做四组实验：压缩率与遮蔽长度消融；连续对比目标对比波形重建；held-out subject/day/rotation/device；负样本来源消融。若模型只在随机窗划分上提高而跨日下降，就说明学到的是会话纹理而非运动语义。BENDR 的价值是提供无需 codebook 的基线，之后再判断离散化是否真的增加跨域复用。', 'bendr')
    }
  },
  {
    id:'biot', title:'BIOT', fullTitle:'BIOT: Biosignal Transformer for Cross-data Learning in the Wild', venue:'NeurIPS 2023', status:'peer-reviewed', source:U.biot[0], pdfSource:U.biot[1],
    slides:{
      positioning:{title:'BIOT：用统一“生理句子”处理格式不一致',sections:['痛点：数据集通道集合、时长、采样率与缺失模式不同','主张：逐通道切段并展平为可变长 token 序列，避免强制补齐整块矩阵','范围：EEG、ECG 与人体活动传感器，支持监督训练和跨数据预训练'],visibleText:'BIOT 的核心贡献不是一种新的掩蔽任务，而是输入接口：把每个通道独立切成固定时长片段，再将所有片段展平成一条“biosignal sentence”。通道缺失时直接缺少相应 token，时长不同只改变序列长度，因此同一 Transformer 可跨数据集训练。每个 token 由 FFT 幅度特征、通道 embedding 与相对位置 embedding 相加得到，并用线性注意力控制长序列代价。对 1 kHz sEMG，这种接口特别适合不同电极数、掉线和不同记录长度，但其频域压缩是否保留连续运动细节必须重新验证。'},
      overviewFigure:{title:'Figure 1：预处理—tokenizer—线性 Transformer—多种学习设置',numberedExplanations:['① 输入可有不同采样率、通道数、时长与缺失片段；先重采样并按每通道 95% 绝对幅值分位数归一化。','② biosignal tokenization 对每个通道独立切固定长度、可重叠的片段，缺失片段对应 token 直接丢弃。','③ 每个片段经 FFT 得到频率能量向量，再线性投影；加通道 embedding 表示空间来源，加相对位置 embedding 表示通道内时间顺序。','④ 所有通道 token 展平成可变长“句子”，交给线性 Transformer 建模跨通道与跨时间交互。','⑤ 编码器上接分类头可做监督学习，也可通过跨数据对比预训练后在另一数据格式上微调。'],visibleText:'Figure 1 上半部分说明一个 BIOT 编码器如何接受任意格式样本，下半部分列出监督、缺失数据、预训练/微调等用法。这里的 tokenizer 是确定性的分段与 FFT 特征生成器，不含可学习 codebook，也不会把片段变成离散 ID。统一来自“token 字段相同”，不是来自把所有数据补成同一矩阵。对 sEMG 可把 electrode/channel ID、腕带角度、左右手和设备 ID 编码为条件；但若把绝对幅值完全分位数归一化，可能损失与连续力/速度相关的信息，需保留幅度旁路。'},
      mechanism:{title:'机制：非参数分段 + FFT token + 线性注意力',modules:['重采样：统一到目标采样率 r；归一化：每通道除以绝对幅值 95% 分位数','分段：长度 t、重叠 p，每通道独立产生 K 个 token；缺失值覆盖的 token 丢弃','token 表示：FFT 能量向量经全连接投影，加可学习通道 embedding 和相对位置 embedding','骨干：线性 Transformer，用 ELU 特征映射近似注意力以降低长“句子”复杂度','预训练：两层投影头后的 NT-Xent/对比目标；同一样本的数据增强视图为正对，批内其他样本为负对'],lossExplanation:'BIOT 的基础编码器可监督训练；跨数据预训练使用对比学习，让同一样本的增强视图接近、其他样本远离。token 本身连续，不存在量化误差或 codebook 交叉熵。',visibleText:'BIOT 把格式兼容问题放在 Transformer 之前解决。其逐通道 token 化允许 64 通道 20 秒样本形成约 1280 token，因此选择线性注意力而非标准二次复杂度注意力。频率向量天然弱化相位，但保留片段内谱能量；通道和相对位置 embedding 恢复“来自哪里、处于何时”。对 sEMG 可采用双路 token：一条 FFT/包络用于鲁棒形态，一条时域卷积用于精细时序；两者融合后再做遮蔽建模或跨日对比，避免 BIOT 单一频谱入口对连续手指轨迹不够敏感。'},
      evidence:{title:'证据：格式鲁棒与跨数据迁移，而非单一“大一统”分数',datasets:['EEG：TUAB 异常检测、TUEV 事件分类、CHB-MIT 癫痫检测等','ECG：包括 PTB-XL 等心电任务；人体活动传感器用于跨模态适用性验证'],metrics:['按任务报告 balanced accuracy、AUROC、AUC-PR 或 F1；CHB-MIT 摘要报告 vanilla BIOT 相对基线约 +3% balanced accuracy，跨源预训练最多再约 +4%','缺失通道、不同片段长度与重叠率均有鲁棒性/超参数比较'],ablations:['比较逐通道 token 化与固定格式模型','研究重采样率、token 长度、重叠和不同预训练来源；跨同模态数据通常比不相关来源更可靠'],limits:['FFT token 弱化相位和瞬时形态，幅度分位数归一化会移除任务相关尺度','通道 embedding 依赖命名体系；未知 sEMG 电极位置和旋转需额外条件化'],visibleText:'BIOT 在 EEG、ECG 和人体活动传感器上证明同一输入接口可工作，并特别测试数据缺失与跨数据预训练。最值得相信的结论是“逐通道 token 化避免格式强对齐带来的障碍”；较弱的结论是任意模态预训练都能互相帮助，因为迁移增益依赖源/目标相似度。论文的指标随数据集变化，不能把摘要中的百分比直接外推到 sEMG。腕带研究应独立报告掉线通道、通道置换、旋转、跨设备和跨人的性能曲线。'},
      transfer:{title:'迁移：把格式兼容做成 sEMG 基座的第一层能力',innovations:['逐通道切段后展平，可自然接受可变通道和缺失片段','FFT、通道与相对时间三种 embedding 解耦信号内容和元数据','线性注意力支持长、多通道序列'],borrow:['构建统一 sEMG token schema：波形/频谱、electrode ID、腕带角度、相对时间、设备与采样率','通道掉线直接用缺失 mask 与变长序列，不强制插补伪信号'],avoid:['不能只保留 FFT 能量；连续运动需要相位、爆发边界和时延信息','不要让设备 ID 或固定通道名成为动作标签捷径'],experiments:['E1：时域卷积 token、FFT token、双路 token 对比，评估手势 macro-F1 与连续轨迹 MAE','E2：随机丢 10%–50% 通道/片段，比较丢 token、零填充和可学习 missing token','E3：训练设备 A/电极数 A，测试设备 B/电极数 B；再做 1%、10% few-shot 适配','E4：held-out subject/day 与腕带旋转 22.5°/45°/90°，比较通道 embedding、几何 embedding 和旋转等变编码'],visibleText:'对 sEMG 最实际的借鉴，是把“输入格式不一致”从数据清洗问题提升为模型设计目标。推荐在 1 kHz 原始波形上保留 20–50 ms 时域支路，同时计算 100–250 ms 频谱/包络支路；每个 token 带通道、时间、腕带朝向和设备元数据。预训练可用掩蔽重建加跨日同动作对比，而不是只复制 BIOT 的实例对比。若模型在通道掉线与跨设备时仍能维持离散手势和连续轨迹性能，才说明“生理句子”接口真正适合通用交互。'}
    },
    notes:{
      positioning:note('BIOT 把多数据生理学习的首要矛盾定义为格式异构，而不是某一种疾病标签。不同 EEG 数据可能有 64 通道 5 秒 256 Hz，也可能是 16 通道 10 秒 200 Hz；传统模型往往先截断、补零或插补到固定矩阵，既浪费信息又引入分布偏移。BIOT 逐通道切段并展平为变长“句子”，使通道和时长差异变成 token 数量差异。论文还覆盖 ECG 与人体活动传感器，说明接口并不依赖 EEG 拓扑。对 sEMG 而言，这比追求一个更大的 Transformer 更基础：设备、电极数量和佩戴位置不统一时，若输入合同不稳，预训练规模越大越可能学到设备捷径。', 'biot'),
      overviewFigure:note('Figure 1 的左侧输入强调格式差异；中间先经过重采样、分位数归一化、逐通道分段和展平，再由 FFT、channel embedding 与 relative position embedding 构造连续 token。右侧线性 Transformer 输出样本表征，可用于监督分类、缺失数据、联合训练或预训练—微调。Figure 2 进一步显示，即便某通道缺失、部分通道较短或存在缺测，只需删除无效 token，仍可构造可比较的句子。这里 tokenizer 不学习离散词汇，codebook 不存在。迁移到腕带时，可将电极角度或物理坐标代替静态名字，使通道 embedding 对旋转与设备布局更有解释性。', 'biot'),
      mechanism:note('BIOT 先统一采样率 r，每通道除以绝对幅值 95% 分位数；随后用长度 t、重叠 p 的滑窗独立切段。每段取 FFT 能量向量并全连接投影，加可学习通道 embedding 和相对位置 embedding。展平后序列可能很长，因此使用 ELU 特征映射的线性 Transformer 近似注意力。监督设置直接接分类头；跨数据预训练使用增强视图的对比损失，同一样本两种变换为正对，批内其他样本为负对。它不是掩蔽重建，也不是离散 token 预测。对 sEMG 应保留幅度旁路，并将频谱 token 与时域卷积 token 并行，否则力度与快速连续运动可能被归一化及相位丢失共同削弱。', 'biot'),
      evidence:note('论文在多项 EEG、ECG 和人体活动任务中分别报告 balanced accuracy、AUROC、AUC-PR 或 F1，并测试跨数据预训练、通道缺失和 token 超参数。摘要以 CHB-MIT 为例：vanilla BIOT 相对强基线约提高 3 个百分点 balanced accuracy，来自其他数据源的预训练最多再带来约 4 个百分点。这里应理解为特定任务结果，而非所有数据的统一平均增益。消融显示 token 长度、重叠和预训练来源会改变结果，格式兼容并不保证无关模态一定正迁移。sEMG 评测要把缺通道、通道置换、旋转和跨设备分开报告，避免一个平均分掩盖失败模式。', 'biot'),
      transfer:note('推荐把 BIOT 改造成双路 sEMG tokenizer：20–50 ms 时域卷积 token 保留爆发边缘和相位，100–250 ms FFT/包络 token 提供频谱与收缩形态；二者共享时间、物理电极角度、腕带朝向和设备 embedding。实验至少包括：不同 token 组合；10%–50% 通道/片段掉线；held-out subject/day/rotation；跨设备及少样本适配。离散手势同时报告 macro-F1、混淆矩阵和检测时延，连续运动报告 MAE、相关系数及高频转折误差。若仅加入设备 ID 就提高同设备测试却降低跨设备测试，应视为条件捷径；几何位置与随机旋转增强更符合通用模型目标。', 'biot')
    }
  },
  {
    id:'labram', title:'LaBraM', fullTitle:'Large Brain Model for Learning Generic Representations with Tremendous EEG Data in BCI', venue:'ICLR 2024', status:'peer-reviewed', source:U.labram[0], pdfSource:U.labram[1],
    slides:{
      positioning:{title:'LaBraM：把连续 EEG 映射为离散“神经词汇”',sections:['规模：约 2,500 小时、约 20 个数据集，模型从 5.8M 扩展到 369M 参数','问题：跨数据集通道数与时长不一，连续波形又缺少类似语言 token 的语义单位','回答：先训练频谱重建驱动的向量量化 tokenizer，再用掩蔽 token 预测预训练 Transformer'],visibleText:'LaBraM 是 EEG 离散 token 路线的代表。它先把每个通道按固定时间窗切成 channel patch，用神经 tokenizer 编码后在 codebook（码本）中做最近邻量化；码本学习并非靠聚类手工特征，而是通过重建原 patch 的 Fourier spectrum 约束 token 保留生理频谱语义。第二阶段遮蔽一部分 EEG patch，Transformer 依据可见通道与时间上下文预测原离散 token。约 2,500 小时、约 20 个数据集和多模型尺度使其能检验数据/参数扩展，但 sEMG 连续运动是否承受量化误差仍需单独验证。'},
      overviewFigure:{title:'Figure 2：先学 tokenizer，再做离散 token 掩蔽预测',numberedExplanations:['① 上半部分把多通道 EEG 切成 channel patch，神经 tokenizer 输出每个 patch 的连续表示。','② 量化器以最近邻在 neural codebook 中查找离散索引；图中的数字代表 token ID，而不是原始振幅。','③ neural decoder 从量化 embedding 重建 patch 的 Fourier spectrum，联合优化频谱重建、commitment 与 codebook 损失。','④ 下半部分对 channel patch 做对称/随机掩蔽；可见 patch 经 temporal encoder 和时空 embedding 形成 Transformer 输入。','⑤ Transformer 输出被遮蔽位置的 token 分布，以 tokenizer 产生的离散 ID 为标签做交叉熵预测。'],visibleText:'Figure 2 清楚区分两个训练阶段：tokenizer 决定“词表是什么”，LaBraM 预训练决定“根据上下文猜什么词”。tokenizer 与 codebook 不是同义词：前者包含编码器、量化器和频谱解码器，后者只是 K 个可学习向量的集合。下游使用 Transformer 表示，不必输出离散 token。对 sEMG，可把码本理解为收缩/协同形态原语，但必须检查同一 token 是否跨受试者、跨日、跨腕带旋转仍对应相似运动学；若 token 只聚类设备或幅度，离散化会制造虚假的可解释性。'},
      mechanism:{title:'机制：VQ 频谱 tokenizer + masked token classification',modules:['输入：任意通道数 EEG，先按样本窗口取样，再以无重叠固定长度 w 对每个通道切 patch','tokenizer：temporal convolution + Transformer 得到 patch 表示，L2 归一化后最近邻查找 K 项 codebook','tokenizer 目标：神经解码器预测 Fourier spectrum；联合频谱重建、codebook 更新与 commitment 约束','主干：加入可学习时间/空间 embedding 的 neural Transformer，patch-wise attention 适配变长通道与时长','预训练目标：遮蔽 patch 的离散 token 交叉熵；不是直接波形 MSE，也不是实例对比'],lossExplanation:'第一阶段损失让量化表示可重建 Fourier spectrum，并用 VQ 项稳定码本；第二阶段固定/复用 tokenizer 产生 token 标签，对被遮蔽位置做分类交叉熵。量化把连续变化压到有限词汇，带来语义压缩也带来信息瓶颈。',visibleText:'LaBraM 的关键假设是：频谱可作为跨数据集稳定的局部语义教师，离散码本可把噪声连续波形压成有限原语。模型通过 channel patch 避免要求固定通道数，并用时间/空间 embedding 标记位置。与 BENDR 相比，目标从连续潜向量对比变成离散 token 分类；与普通 masked autoencoder 相比，它不直接回归原始波形。迁移 sEMG 时建议保留连续分支，与 VQ 分支联合训练：离散分支服务手势原语，连续分支保留角度、速度和力度细节。'},
      evidence:{title:'证据：多任务迁移与 scaling，但码本语义仍是间接证据',datasets:['预训练：约 2,500 小时、约 20 个公开及自采 EEG 数据集','下游：TUAB 异常检测、TUEV 事件分类、SEED 系列情绪识别、步态预测等分类与回归任务'],metrics:['按任务报告 balanced accuracy、AUROC、weighted F1、accuracy 或回归指标；论文结论是 LaBraM 在四类下游相对当时基线取得领先','模型规模 5.8M 至 369M；数据量与模型尺度实验显示预训练资源增加通常改善迁移，但收益依任务而异'],ablations:['比较随机初始化、不同预训练数据规模、模型大小和 tokenizer/codebook 组件','可视化 token 使用与频谱模式，为离散词汇提供解释线索，但未证明 token 与具体生理事件一一对应'],limits:['固定 EEG 空间词表依赖 10–20 通道集合，未知阵列需映射','频谱重建弱化相位，量化可能损失连续回归所需的细粒度变化'],visibleText:'LaBraM 的实验覆盖异常、事件、情绪和步态，证明离散预训练可服务分类与回归，而不只是一个任务。其规模实验支持更多数据与更大模型在若干设置下有收益，但论文没有给出可直接外推到 sEMG 的普适 scaling law。码本可视化显示 token 与频谱形态相关，却不能据此断言 token 就是生理原语。对腕部 sEMG，必须用运动学邻域一致性、跨域 token 稳定性、码本利用率和连续轨迹误差联合验证，尤其防止 codebook collapse。'},
      transfer:{title:'迁移：把 codebook 当作待证假设，而非默认答案',innovations:['频谱监督使 tokenizer 学到比波形聚类更稳定的离散 token','两阶段训练把局部词汇学习与长程上下文建模分开','通道 patch 支持变长通道/时长输入'],borrow:['建立 sEMG VQ 支路：短窗时频表示量化为收缩 motif，主干做 masked token prediction','保留连续潜支路，与离散支路共享骨干，分别服务连续运动和离散手势'],avoid:['不要用过大的 codebook 在有限人群上记住受试者/设备','不要仅以重建频谱或 token 可视化证明运动语义；需跨域及运动学验证'],experiments:['E1：连续 token、VQ token、连续+VQ 双分支三组预训练对照','E2：codebook 大小 128/512/2048，报告 perplexity、死码比例、跨日 token 一致性和下游双任务指标','E3：频谱重建、时域重建、同步 IMU/关节速度重建作为 tokenizer 教师的比较','E4：held-out subject/day/device/rotation 下统计同动作 token 分布距离与不同动作可分性'],visibleText:'sEMG 中可以借鉴 LaBraM 的两阶段逻辑，但不应预设离散词汇必然最好。建议先用 20–100 ms patch 训练含 128–2048 个码字的 tokenizer，同时保留连续残差；主干对被遮蔽 token 做分类，并联合预测未来关节运动学。离散手势看 macro-F1 和样本效率，连续运动看 MAE、相关系数和相位延迟；再用 held-out subject、跨日、跨设备和腕带旋转检验 token 稳定性。如果较小码本提升手势却损害连续轨迹，双分支就是更合理的折中。'}
    },
    notes:{
      positioning:note('LaBraM 汇集约 2,500 小时、约 20 个不同任务和格式的 EEG，并训练 5.8M 到 369M 参数的模型。它把 EEG 基础模型的难点拆成三件事：如何兼容通道与时长，如何从连续波形得到适合分类式掩蔽预测的目标，以及数据/模型扩展是否有效。解决方法是 channel patch 加神经 tokenizer：每个通道独立切固定窗，tokenizer 用向量量化将连续 patch 映射到 neural codebook，随后 Transformer 预测被遮蔽位置的离散 ID。对 sEMG 的价值在于提供可检验的“肌肉词汇”路线，但 codebook 是否跨人、跨日和跨设备稳定，必须用运动交互标签而不是视觉印象来验证。', 'labram'),
      overviewFigure:note('Figure 2 上半部分是 neural tokenizer training：EEG patch 经编码器成为连续表示，最近邻查 codebook 得离散 token，量化 embedding 经 decoder 重建 Fourier spectrum。损失同时约束频谱重建、codebook 向编码器表示靠近和编码器对选中码字的 commitment。下半部分是 LaBraM pre-training：部分 channel patch 被遮蔽，可见 patch 加时空 embedding 后进入 neural Transformer，输出被遮蔽位置的 token 分布。两个阶段要严格区分；tokenizer 是完整映射系统，codebook 只是其中的可学习向量表。迁移到 sEMG 时，图中频谱监督可替换或补充为同步运动学监督，以避免词表只描述设备频响。', 'labram'),
      mechanism:note('LaBraM 将 EEG 样本按时间窗取样，再把每通道以无重叠长度 w 切成 patch。temporal convolution 编码局部形态，时间和空间 embedding 标出位置，Transformer 负责 patch-wise 交互。tokenizer 阶段对 patch 表示和 codebook 向量做 L2 归一化最近邻量化，解码 Fourier spectrum；主干阶段把 tokenizer 输出的离散 ID 当标签，对被遮蔽 patch 做交叉熵分类。它不是对比学习，也不直接回归原始波形。VQ 的优势是目标稳定、分类空间有限；代价是量化误差和死码。对连续手指/腕部运动，建议增加连续 residual token 或运动学预测头，不能让码字吞掉细粒度幅度变化。', 'labram'),
      evidence:note('论文在异常检测、事件分类、情绪识别和步态预测四类任务上评测，并比较不同模型规模、预训练数据量与随机初始化。结果整体支持大规模预训练和离散 token 目标优于多种当时基线，但不同任务使用不同指标，不能用一个总分概括。模型从 5.8M 扩到 369M，更多参数和数据通常改善迁移，却并非说明 sEMG 也需要数亿参数。token 可视化与频谱相关，只是“码字保留频谱语义”的间接证据；它没有证明某个码字对应单一脑状态。sEMG 需要额外报告码本 perplexity、死码比例、同动作跨域一致性和连续运动误差，才能判断离散化是否真正有用。', 'labram'),
      transfer:note('建议以 LaBraM 为第二阶段实验，而不是首个默认方案。先建立连续 masked reconstruction 基线，再加入 VQ tokenizer：比较 128、512、2048 个码字，频谱、时域、同步 IMU/关节速度三类 tokenizer 教师，以及连续、离散、双分支表示。严格 held-out subject/day/device/rotation，并统计同动作 token 分布在域变化前后的 Jensen–Shannon 距离；离散手势报告 macro-F1，连续轨迹报告 MAE、相关系数和时延。若 token 在跨日仍稳定且少样本手势明显获益，同时连续轨迹无损，码本才成立；若死码多或 token 按设备聚类，应缩小词表或退回连续目标。', 'labram')
    }
  },
  {
    id:'eegpt_wang', title:'EEGPT', fullTitle:'Pretrained Transformer for Universal and Reliable Representation of EEG Signals', venue:'NeurIPS 2024', status:'peer-reviewed', source:U.eegpt_wang[0], pdfSource:U.eegpt_wang[1],
    slides:{
      positioning:{title:'EEGPT：同时对齐特征与重建波形的双自监督',sections:['问题：EEG 非平稳、通道不一致，单纯重建可能只学局部数值','方案：遮蔽输入由 online encoder/predictor 预测完整输入的 momentum encoder 表示','补充：reconstructor 同时恢复原 patch，联合特征对齐与波形重建'],visibleText:'EEGPT 用约一千万参数的 Transformer 处理多任务 EEG。它把多通道信号切成“通道 × 时间”的 patch 网格，以 local spatio-temporal embedding 编码；预训练时遮蔽 50% 时间块与 80% 通道 patch。online encoder 只看可见部分，predictor 根据 mask token 推断被遮蔽位置；momentum encoder 看完整输入并提供停止梯度的特征目标，reconstructor 再回归原始 patch。两条损失分别约束抽象表征和局部波形，可减少纯 MSE 只学平滑插值的问题。对 sEMG，这种连续教师目标比过早 codebook 更适合兼顾手势和连续运动。'},
      overviewFigure:{title:'Figure 1：online 分支、momentum 教师与波形重建',numberedExplanations:['① 多通道 EEG x 被切为 p_i,j，local spatio-temporal embedding 加入通道和时间局部信息。','② 图中同时执行 50% 时间遮蔽和 80% 通道 patch 遮蔽，online encoder 只编码可见 token 并用 summary token 汇聚每个时间段。','③ predictor 接收 online 特征和代表被遮蔽位置的 mask/query token，输出被遮蔽位置预测表示。','④ momentum encoder 读取完整、未遮蔽 token，以指数滑动平均更新参数，产生 feature-alignment 教师目标。','⑤ reconstructor 把预测表示与编码特征融合，重建原始 patch；Alignment Loss 与 Reconstruction Loss 相加。'],visibleText:'Figure 1 的关键是同一掩蔽样本产生两种监督：上方 momentum encoder 规定“隐藏 patch 在表示空间应是什么”，右侧 reconstructor 规定“原始波形应恢复为什么”。没有离散 codebook，也没有批内正负样本；所谓 alignment 是均方误差式教师—学生特征对齐，不是 SimCLR 对比学习。对腕部 sEMG 可将通道遮蔽理解为模拟电极掉线或旋转造成的信息缺失，时间遮蔽模拟动作片段缺失；但 80% 通道遮蔽可能过强，应按实际设备冗余重新标定。'},
      mechanism:{title:'机制：局部时空 embedding + EMA 教师的双目标',modules:['输入：M 通道 × T 时间点切为通道 patch；局部时空 embedding 以卷积/位置编码保留邻域','掩蔽：论文 Figure 1 标注 50% 时间、80% 通道 patch；online encoder 处理可见集合','predictor：以可见 summary/patch 特征和 mask query 推断隐藏位置表示','momentum encoder：完整输入的指数滑动平均教师，停止梯度提供目标特征','reconstructor：由预测特征回归原 patch；总损失 L = L_A + L_R，二者均为 MSE 型连续目标'],lossExplanation:'L_A 对齐 predictor 与 momentum encoder 的隐藏位置表示；L_R 对齐重建 patch 与原始 p_i,j。没有负样本、量化或 token 分类，token 始终为连续 embedding。',visibleText:'EEGPT 借鉴 JEPA/EMA 教师思想，将高层特征预测与低层波形恢复结合。特征对齐促使模型学习跨时空一致性，波形重建避免表示只保留任务捷径。local spatio-temporal embedding 让通道与时间依赖在进入 Transformer 前已有局部归纳偏置。对 1 kHz sEMG，建议把 raw patch MSE 换为时域 + log-spectrum + envelope 多项重建，并让教师看到弱增强完整信号、学生看到旋转/掉线/时间遮蔽后的强增强，从而直接学习佩戴鲁棒性。'},
      evidence:{title:'证据：跨任务 EEG 迁移与鲁棒性，仍需警惕数据重叠和协议差异',datasets:['预训练混合 PhysioMI、HGD、M3CV 等多任务 EEG 数据','下游覆盖运动想象、情绪、睡眠、异常/事件等任务，采用线性探测与微调'],metrics:['按任务报告 accuracy、balanced accuracy、AUROC、F1 或 kappa；论文整体结论是 EEGPT 在多项基准取得竞争性或领先结果','鲁棒性实验考察通道数量/布局变化、噪声或数据规模设置'],ablations:['比较只做重建、只做对齐和双损失；联合目标通常更稳','比较掩蔽策略、local spatio-temporal embedding 与预训练初始化'],limits:['混合数据集的采样与划分协议不统一，结果不能视为一个总体临床结论','教师—学生可能共同保留设备/受试者特征；跨域不变性仍需显式 held-out 验证'],visibleText:'EEGPT 的价值主要来自跨任务一致性：它不是只在一个分类数据集上验证，而是用多种下游说明表示可迁移。消融支持特征对齐与波形重建互补，并显示局部时空 embedding 和预训练有贡献。不过不同下游指标与切分不一致，不能简单平均；“universal”也不等于已验证跨腕带设备。对 sEMG 应复现实验逻辑而非结论：同一骨干在离散手势、连续运动学、跨人、跨日、旋转、位移和跨设备协议上统一比较，尤其监控重建很好但动作表征退化的情况。'},
      transfer:{title:'迁移：推荐作为 sEMG 主方案的连续教师—学生骨架',innovations:['特征级预测与波形级重建互补','momentum teacher 无需负样本，降低假负样本风险','时域与通道联合遮蔽可模拟实际传感缺失'],borrow:['教师看完整弱增强 sEMG，学生看跨度遮蔽、通道掉线、腕带旋转增强','重建头联合 raw、包络、频谱；表示头预测教师连续 latent'],avoid:['不要直接使用 80% 通道遮蔽；低通道设备可能无信息可用','避免教师与学生共享设备 ID 捷径，跨设备批次需平衡'],experiments:['E1：L_R、L_A、L_R+L_A 三组预训练；双下游统一评测','E2：时间遮蔽 20%–70%、通道遮蔽 10%–60%，与真实掉线/旋转鲁棒性关联分析','E3：EMA teacher vs 共享权重 teacher vs 无 teacher，比较稳定性与坍塌指标','E4：held-out subject/day/rotation/displacement/device，外加 1%/10% 标签微调曲线'],visibleText:'在当前目标下，EEGPT 式双目标是最值得优先实现的主干：它保留连续信息，避免为手势牺牲连续轨迹，又能用教师表征降低纯重建的低级插值偏差。建议 1 kHz sEMG 以多尺度 patch 输入，学生端施加时间跨度、通道掉线、幅度缩放与物理旋转，教师端只做弱增强；总损失包含教师 latent 对齐、时域/频域/包络重建，再选配未来运动学预测。最终用离散手势与连续手指/腕部轨迹同等权重选择模型。'}
    },
    notes:{
      positioning:note('EEGPT 面向 EEG 非平稳、通道不匹配和任务差异，提出约一千万参数的预训练 Transformer。与只回归原始波形的 masked autoencoder 不同，它增加 momentum encoder 教师：online encoder 只看遮蔽后的输入，predictor 预测隐藏位置的高层表示；momentum encoder 看完整输入，提供稳定的连续特征目标；reconstructor 再恢复原 patch。预训练混合 PhysioMI、HGD、M3CV 等多任务数据。对 sEMG 而言，这一结构正好兼顾抽象运动语义和连续波形细节，且不依赖负样本或离散码本，适合作为主方案而不是附属基线。', 'eegpt_wang'),
      overviewFigure:note('Figure 1 展示 patching、local spatio-temporal embedding、masking、encoder、predictor、momentum encoder 和 reconstructor。图注明确标出 50% 时间与 80% 通道 patch 遮蔽。online encoder 只接收可见 token，并以 summary token 汇聚；predictor 用 mask/query token 查询隐藏位置。完整 token 进入 momentum encoder，参数由 online encoder 的指数滑动平均更新，输出停止梯度的目标。reconstructor 将预测表示与可见编码结合恢复原始 patch。两条箭头对应 Alignment Loss 与 Reconstruction Loss，均为连续 MSE 型目标；不存在 codebook、离散 token ID 或对比负样本。', 'eegpt_wang'),
      mechanism:note('输入 x∈R^{M×T} 被切成通道—时间 patch p_i,j，并通过局部时空 embedding 形成连续 token。online encoder 处理可见部分，predictor 为隐藏位置生成表示；momentum encoder 处理完整样本并以 EMA 更新，提供 feature alignment 目标。reconstructor 再把预测表示解码到 raw patch。总损失是 L_A 与 L_R 相加：前者约束抽象表示一致，后者约束波形可恢复。迁移到 sEMG 时可把 raw MSE 扩展为时域、log-spectrum 和 envelope 重建，并让教师/学生采用不对称增强；但需确保教师目标不携带受试者或设备捷径，批次采样和跨域验证同样重要。', 'eegpt_wang'),
      evidence:note('论文在运动想象、情绪、睡眠及异常/事件等多类 EEG 下游做线性探测和微调，指标随任务使用 accuracy、balanced accuracy、AUROC、F1 或 kappa。消融比较单独重建、单独特征对齐与联合损失，联合目标总体更稳定；也验证 local spatio-temporal embedding、掩蔽策略和预训练初始化的贡献。应谨慎理解“universal”：混合预训练与不同下游的采样率、通道、划分和指标并不统一，模型尚未证明对所有真实设备自然鲁棒。sEMG 必须把 held-out subject、day、rotation、displacement 和 device 写进主协议，而非附录。', 'eegpt_wang'),
      transfer:note('具体实现可设置 20–50 ms 局部 patch 和 200–500 ms上下文分组：教师接收完整弱增强 sEMG，学生接收 20%–70% 时间遮蔽、10%–60% 通道遮蔽以及物理一致的腕带旋转。预训练比较 L_R、L_A 和联合目标，再比较 EMA teacher、无 teacher 与共享权重 teacher。下游以相同 backbone 评估手势 macro-F1/检测时延与连续角度 MAE/相关系数；跨人、跨日、跨旋转、沿前臂位移和跨设备都要报告。若联合目标在低标签与跨域条件同步提升两类任务，就构成基座有效性的核心证据。', 'eegpt_wang')
    }
  },
  {
    id:'cbramod', title:'CBraMod', fullTitle:'CBraMod: A Criss-Cross Brain Foundation Model for EEG Decoding', venue:'ICLR 2025', status:'peer-reviewed', source:U.cbramod[0], pdfSource:U.cbramod[1],
    slides:{
      positioning:{title:'CBraMod：把 EEG 的“同通道时间”与“同时刻空间”分开建模',sections:['批评：full attention 把所有 patch 一视同仁，忽略 EEG 的十字形强依赖结构','方案：criss-cross attention 并行执行空间注意力与时间注意力','适配：ACPE 用非对称卷积动态编码不同通道数与时长的位置'],visibleText:'CBraMod 认为 EEG patch 的主要依赖不是任意二维全连接：同一通道跨时间、同一时间跨通道更强，因此在每个 Transformer block 中并行执行 S-Attention 和 T-Attention，再融合结果。输入 patch 还有双路编码：时域卷积提取局部波形，FFT 能量支路提取频域特征。预训练对 30 秒、200 Hz 的 TUEG 样本按 1 秒 patch 切分，随机遮蔽 50%，以 MSE 重建原波形。它没有 codebook 或教师网络。对环形 sEMG 阵列，这种轴向分解可改为“沿腕带空间邻域 × 动作时间”，但旋转会改变通道索引，必须加入物理坐标或等变处理。'},
      overviewFigure:{title:'Figure 2：双路 patch 编码、ACPE 与 criss-cross Transformer',numberedExplanations:['① 多通道 EEG 先按固定时间窗切成 C×n 个 patch，并以 Bernoulli mask token 随机替换部分 patch。','② patch encoder 左支用多层时间卷积提取时域形态，右支用 FFT 能量向量提取频域信息，两支融合成 embedding。','③ ACPE 以空间和时间核尺寸不同的非对称卷积，从邻域动态生成位置编码并加回 patch embedding。','④ 每个 criss-cross block 并行执行同一时间片跨通道 S-Attention，以及同一通道跨时间 T-Attention。','⑤ reconstruction head 从隐藏表示重建被遮蔽 EEG patch，以原始波形 MSE 训练。'],visibleText:'Figure 2 从“Masked EEG”到重建输出展示完整预训练路径。图中 patch embedding 始终连续；FFT 只是 patch encoder 的一个支路，不产生离散频谱 token。ACPE 与绝对 channel embedding 不同，它依据当前 C×n 网格卷积生成条件位置，因此能适配不同通道数和时长。criss-cross 不是先空间后时间的轴向堆叠，而是在同一 block 内并行建模后融合。对于 sEMG，应将空间卷积设计为环形/物理角度邻域，并用旋转增强检验位置编码是否真正跨佩戴。'},
      mechanism:{title:'机制：时频连续 patch 的掩蔽重建',modules:['预处理：TUEG 清洗后统一 200 Hz，切为 30 秒样本；1 秒 patch，序列每通道 30 个 patch','掩蔽：Bernoulli 采样约 50% patch，以全零 mask token 替换','patch encoder：Conv1D 时域支路 + FFT 能量/线性频域支路，输出连续 embedding','位置与骨干：ACPE 非对称二维卷积；12 层 criss-cross Transformer 并行空间/时间注意力','目标：reconstruction head 回归被遮蔽原始 patch，使用 MSE；无负样本、无教师、无量化'],lossExplanation:'损失只在掩蔽 EEG patch 上计算波形重建误差。模型通过可见同通道时间上下文与同时刻跨通道上下文插补隐藏 patch，时频编码和 ACPE 提供归纳偏置。',visibleText:'CBraMod 的“结构创新”与“目标创新”要分开看：预训练目标仍是标准连续波形掩蔽重建，性能提升主要来自 patch encoder、ACPE 和 criss-cross attention。论文还强调预训练数据清洗：直接用含大量坏片段的 TUEG，效果只略好于不预训练；清洗后预训练均值更高、方差更小。对 sEMG，这提示接触脱落、饱和和工频污染不能只靠模型吞掉；需要质量标记、坏段过滤及把真实通道缺失作为显式增强。'},
      evidence:{title:'证据：12 个数据集、10 个任务与结构消融',datasets:['预训练：清洗后的 TUEG，200 Hz、30 秒样本、19 通道设置','下游 12 个公开数据集/10 类任务；含 FACED/SEED-V 情绪、PhysioNet-MI/SHU-MI 运动想象、睡眠、癫痫、想象语音、警觉度等'],metrics:['PhysioNet-MI：CBraMod Cohen’s kappa 0.5222，对 LaBraM-Base 0.4912；SHU-MI AUROC 0.6988，对 BIOT 0.6609','任务分别报告 balanced accuracy、kappa、weighted F1、AUC-PR、AUROC 或回归指标'],ablations:['criss-cross attention 优于 full、轴向顺序注意力与 CCNet 单图注意力','ACPE 优于无位置、APE 与普通 CPE；clean pre-training 优于 dirty 和无预训练'],limits:['空间轴仍依赖通道排列，不能自动解决腕带旋转或未知电极拓扑','波形 MSE 容易偏向低频/高能量片段；跨域鲁棒并未覆盖 sEMG 设备扰动'],visibleText:'CBraMod 的证据链比单一 SOTA 表更完整：Figure 4 比较注意力结构，Figure 5 比较位置编码，Table 4 比较 clean、dirty 和无预训练。以运动想象为例，它在 PhysioNet-MI 和 SHU-MI 的关键指标上超过 BIOT/LaBraM 基线；但这些仍是 EEG 任务，不能证明对 sEMG 环形阵列同样有效。最有价值的可迁移结论是并行时空建模与数据质量控制，而非具体数值。sEMG 要增加环形移位、沿前臂位移、跨日和跨设备压力测试。'},
      transfer:{title:'迁移：环形空间 × 时间的结构化 sEMG Transformer',innovations:['并行空间/时间注意力显式编码多通道时序结构','ACPE 动态适配网格尺寸','时域与频域双路 patch encoder'],borrow:['把 S-Attention 改成环形邻域/电极角度注意力，把 T-Attention用于动作动态','预训练前建立信号质量评分；坏段过滤与真实掉线增强并存'],avoid:['不要把通道编号当固定解剖位置；旋转后相同编号对应不同肌肉区域','不要只用 raw MSE，避免模型忽略小幅但动作相关的高频变化'],experiments:['E1：full、factorized axial、criss-cross、环形等变 attention 四组结构对照','E2：APE、ACPE、物理角度编码、旋转相对位置编码在 0°–180° 旋转下比较','E3：raw MSE、时频多目标、教师 latent 对齐三组预训练目标','E4：clean-only、dirty-only、质量加权训练，按 held-out subject/day/device/displacement 评估'],visibleText:'推荐把 CBraMod 的结构用于 sEMG，而不是原封不动复制其损失。每个 20–100 ms patch 同时提取时域卷积与 log-spectrum，空间注意力沿腕带圆周建模电极协同，时间注意力跟踪手势和连续轨迹；位置编码使用真实角度和相对旋转。训练目标可用时频重建加 EEGPT 式教师 latent 对齐。必须同时比较离散手势 macro-F1 与连续运动 MAE/相关系数，并在腕带旋转、位移、跨日、跨人和跨设备下报告，才能证明结构先验而非固定布局记忆带来收益。还应同步报告端侧吞吐、显存占用与因果流式延迟。'}
    },
    notes:{
      positioning:note('CBraMod 的出发点是 EEG patch 网格具有非图像式结构：同一通道跨时间以及同一时刻跨通道的依赖更强，full attention 平等连接所有 patch 既昂贵又忽略先验。作者提出 criss-cross Transformer，在每个 block 内并行计算空间注意力和时间注意力；同时用 asymmetric conditional positional encoding（ACPE）动态生成位置编码，适配不同通道数与时长。预训练仍是连续波形掩蔽重建。对腕部 sEMG，最可借鉴的是结构化空间—时间分解，但通道环形排列会随腕带旋转改变，因此必须把绝对索引升级为物理角度或旋转等变表示。', 'cbramod'),
      overviewFigure:note('Figure 2 展示五个关键部件：EEG patching 与随机 masking；时域卷积和 FFT 能量双路 patch encoder；ACPE 通过空间、时间非对称卷积编码邻域位置；多层 criss-cross Transformer；reconstruction head 恢复 masked patch。Figure 3 进一步说明 S-Attention 在同一时间跨通道计算，T-Attention 在同一通道跨时间计算，两者并行而不是前六层空间、后六层时间。图中 token 均为连续 embedding，FFT 支路不是 tokenizer，系统没有 codebook。迁移 sEMG 时应把空间轴做成圆周边界，避免首尾电极被错误视为不相邻。', 'cbramod'),
      mechanism:note('预训练将清洗后的 TUEG 统一到 200 Hz，切成 30 秒样本；每个通道按 1 秒即 200 点 patch 分割，约 50% patch 用全零 mask token 替换。patch encoder 一支用 Conv1D 提取时域形态，一支对 FFT 能量向量投影，两者融合。ACPE 根据 C×n 网格动态生成位置，12 层 criss-cross block 并行汇聚空间与时间上下文。重建头以 MSE 预测原始 masked EEG patch；没有对比正负样本、EMA 教师或向量量化。对 sEMG 可将 raw MSE 扩展为时域、包络和频谱加权损失，并把真实掉线纳入 mask 分布。', 'cbramod'),
      evidence:note('CBraMod 在 12 个公开数据集、10 类下游任务上评估。运动想象中，PhysioNet-MI 的 Cohen’s kappa 为 0.5222，对比 LaBraM-Base 0.4912；SHU-MI 的 AUROC 为 0.6988，对比 BIOT 0.6609。更关键的是消融：criss-cross attention 优于 full、顺序 axial 和 CCNet 注意力；ACPE 优于无位置、APE 与普通 CPE；clean pre-training 在均值和方差上优于 dirty 与无预训练。论文也显示脏 TUEG 只带来有限收益，说明数据质量是基础模型变量。上述证据仍未覆盖腕带旋转、位移或跨设备，不能直接当作 sEMG 泛化结论。', 'cbramod'),
      transfer:note('sEMG 实验应构建“环形空间×时间”版本：空间注意力采用圆周相对距离或真实电极角度，时间注意力建模 0.5–4 秒动作上下文；双路 patch encoder 保留 1 kHz 时域高频与中窗频谱。至少比较 full、顺序 axial、原 criss-cross 和环形等变 attention；比较 APE、ACPE、物理角度与旋转相对位置；比较 raw MSE、时频重建与教师 latent 对齐。评测按 held-out subject、day、rotation、沿前臂 displacement 和 device 展开，同时报告手势 macro-F1 与连续轨迹 MAE/相关系数。数据质量实验要区分过滤坏段、质量加权和把坏段作为增强。', 'cbramod')
    }
  },
  {
    id:'neuript', title:'NeurIPT', fullTitle:'NeurIPT: Foundation Model for EEG with Amplitude-Aware Pretraining and Progressive Mixture-of-Experts', venue:'NeurIPS 2025', status:'peer-reviewed', source:U.neuript[0], pdfSource:U.neuript[1],
    slides:{
      positioning:{title:'NeurIPT：把 EEG 异质性拆成幅度、时间模式与空间布局',sections:['数据：使用超过 2,000 小时、排除下游测试集的 EEG 做预训练','时间：Amplitude-Aware Masked Pretraining（AAMP）避免随机遮蔽退化为局部插值','结构：Progressive Mixture-of-Experts（PMoE）让深层逐步增加专门专家','空间：真实三维电极坐标与 Intra-Inter Lobe Pooling（IILP）适配不同 montage'],visibleText:'NeurIPT 面向跨数据集 EEG 的三类异质性：振幅和事件强度不同、时间动力学不同、电极布局不同。它以幅度感知掩蔽选择更有信息的片段，迫使模型从上下文恢复而非简单插值；以渐进式专家混合让浅层共享低级模式、深层分工处理复杂动态；以电极三维坐标和脑叶内/脑叶间池化处理空间差异。论文在八个 BCI 下游数据集上微调。对腕部/前臂 sEMG，三维脑叶先验不能照搬，但“能量感知掩蔽 + 共享到专门的渐进路由 + 物理电极坐标”具有直接参考价值。'},
      overviewFigure:{title:'Figure 3：AAMP、三维电极位置、PMoE 与 IILP 的完整链路',numberedExplanations:['① 左下蓝色路径把原始多通道 EEG 与电极三维坐标共同送入 3D Electrode Embedding，空间位置不是固定通道编号。','② 左侧 Amplitude-Aware Masking 根据每通道信号幅度区间选择遮蔽区域，避免模型仅靠相邻点插值恢复。','③ 中间 encoder block 交替使用 temporal attention、spatial attention 与 Progressive MoE，越深层可用的专门专家越多。','④ 预训练端的轻量 decoder 用时间自注意力与前馈网络重建被遮蔽信号，以连续重建误差训练。','⑤ 下游端通过 IILP 先聚合同一脑叶，再建模脑叶之间关系，最后形成分类表示。'],visibleText:'Figure 3 将预训练和微调画在同一张图：左侧信号经过幅度感知遮蔽与三维位置 embedding，中央多层 encoder 同时学习时间、空间和专家路由；上方左支在预训练时接 decoder 重建，右支在下游时接 IILP 和分类头。图中没有向量量化或 codebook，token 始终是连续表示。PMoE 的“progressive”不是训练日程逐步加专家，而是网络深度越高，专门专家数量越多，同时保留共享专家。迁移到环形腕带时，可用真实电极角度、腕围与轴向位置替代脑叶坐标。'},
      mechanism:{title:'机制：幅度驱动的困难遮蔽 + 渐进专家路由',modules:['输入表示：多通道样本与电极 3D 坐标共同编码，减少对固定通道表的依赖','AAMP：按通道幅度统计确定候选遮蔽区，优先覆盖具有能量/事件信息的片段','双轴注意力：temporal attention 建模同通道时间依赖，spatial attention 建模同时刻通道关系','PMoE：共享专家保持通用表示，专门专家随深度从少到多；router 对 token 进行稀疏分配','预训练与微调：decoder 重建连续 EEG；下游使用 IILP 聚合脑叶局部与全局特征'],lossExplanation:'预训练目标是被 AAMP 遮蔽位置的连续信号重建，重点创新在遮蔽分布而非新损失。专家由路由权重选择；没有离散 token 交叉熵、对比负样本或 EMA 教师。',visibleText:'随机时间遮蔽在平滑时序上可能变成容易的插值题，AAMP 通过幅度筛选提高隐藏片段的信息量。PMoE 假设低层局部形态可共享，而深层语义需要更多专家；共享专家用于防止完全碎片化。IILP 只在微调阶段利用脑叶分区。对 sEMG 可把幅度改为多指标难度分数，例如整流能量、谱通量和包络变化；若只遮蔽最高能量爆发，模型会忽略低幅精细指动，因此应混合能量分层采样。专家路由也应以动作阶段与信号形态为依据，不能直接喂受试者 ID。'},
      evidence:{title:'证据：八个 BCI 数据集与组件级消融',datasets:['预训练：超过 2,000 小时公开 EEG，并显式排除八个下游数据集','下游覆盖 TUEV、MentalArithmetic、Mumtaz2016、SEED-V、PhysioP300、BCIC-IV-2A 等八个不同 BCI 场景'],metrics:['按任务报告 balanced accuracy、weighted F1、AUROC、AUC-PR 或 Cohen’s kappa，不能合并为单一平均分','论文报告在多数下游相对 BENDR、BIOT、LaBraM、EEGPT、CBraMod 等基线达到领先或竞争结果'],ablations:['progressive 专家数量随深度增加优于无专家和 shrinking 配置，多个渐进分配均表现稳定','IILP 优于无池化及冠状面、矢状面、半球分组；3D PE、PMoE、IILP 组合总体最佳','不同激活函数与专家参与可视化用于检查路由行为'],limits:['专家路由可能按数据集或设备域分工而非生理语义，需额外域泄漏分析','脑叶分区是 EEG 专属先验；sEMG 没有可直接对应的离散区域标签'],visibleText:'NeurIPT 的证据价值在于消融覆盖“遮蔽—空间—专家—池化”多个层面，而非只报告一个总表。Table 3 比较无专家、shrinking 和 progressive，Table 5 比较不同空间池化，Table 6 从头训练拆除单个组件；结果支持渐进专家与 IILP 的贡献。八个任务跨精神压力、精神障碍、情绪、P300、运动想象与事件识别，但仍主要是分类。对 sEMG 必须增加连续轨迹回归，并检查专家是否只识别设备、受试者或强度区间；若路由可预测域标签却不能提高 held-out 域，说明发生了捷径学习。'},
      transfer:{title:'迁移：以困难片段采样和轻量专家处理 sEMG 异质性',innovations:['以信号内容决定遮蔽难度，而非均匀随机 mask','共享专家 + 深层渐增专门专家兼顾公共模式与异质动力学','物理电极坐标代替僵硬通道编号'],borrow:['用腕带圆周角、沿前臂位置和左右手编码空间关系；AAMP 改为能量/谱通量/包络变化分层采样','先用共享骨干，只有数据规模足够后在高层加入 2–4 个轻量专家'],avoid:['不要把受试者、设备或动作标签直接作为 router 输入，避免域标签泄漏','不要只遮蔽高能爆发；低幅精细手指动作同样是核心语义'],experiments:['E1：随机遮蔽、仅高能遮蔽、能量分层混合遮蔽，比较重建难度与双下游迁移','E2：无专家、静态 4 专家、shrinking、progressive 2→4 专家，报告路由熵和专家负载','E3：固定通道 ID、物理角度、圆周相对位置三种空间编码，测试 22.5°–90° 旋转','E4：held-out subject/day/device/displacement，评估手势 macro-F1 与连续角度 MAE/相关系数'],visibleText:'NeurIPT 最适合贡献两项 sEMG 消融：遮蔽“什么片段”以及模型“何时需要专家”。推荐先以多尺度连续 token 构建无 MoE 基线，再加入能量分层掩蔽；若低幅手指微动被漏学，则提高低能但高谱通量片段采样。PMoE 只放在高层，并通过负载均衡、路由熵和域可预测性检查是否坍塌。空间位置使用腕带圆周相对角度和沿前臂坐标。最终必须同时在离散手势与连续轨迹上取得跨人、跨日、旋转、位移、跨设备增益，才能证明专家捕获的是运动动力学而不是数据集来源。'}
    }
  },
  {
    id:'tfm_tokenizer', title:'TFM-Tokenizer', fullTitle:'Tokenizing Single-Channel EEG with Time-Frequency Motif Learning', venue:'ICLR 2026', status:'peer-reviewed', source:U.tfm_tokenizer[0], pdfSource:U.tfm_tokenizer[1],
    slides:{
      positioning:{title:'TFM-Tokenizer：让离散词汇真正成为下游输入',sections:['问题：多数 EEG“tokenization”只是定长切窗，并未学习可复用词表','差异：LaBraM 的 VQ token 主要提供预训练标签，TFM token 在下游仍作为模型输入','目标：单通道学习时间—频率 motif，跨通道、跨设备组合使用'],visibleText:'TFM-Tokenizer 直接追问“EEG token 到底应是什么”。它把 token 定义为短时重复的时间—频率 motif，而不是任意固定窗。单通道原始 EEG 与 STFT 谱图走双路径：时间编码器保留波形上下文，Localized Spectral Window Encoder 提取局部频带结构；两者经 temporal Transformer 融合并量化到离散 vocabulary。训练时同时遮蔽时间和频带，要求解码器重建谱图。生成的 token ID 在第二阶段直接输入下游 Transformer，并做 masked token prediction。其优势是跨通道配置和耳 EEG 设备可复用，风险是码本可能牺牲 sEMG 连续运动的细粒度。'},
      overviewFigure:{title:'Figure 2：双路径 motif tokenizer 与下游 token 预训练',numberedExplanations:['① 左上单通道 EEG 以重叠 patch 输入 temporal encoder，同时计算 STFT 得到时间—频率谱图。','② 左下对谱图施加 temporal mask 与 frequency-band mask，Localized Spectral Window Encoder 分频带编码并门控聚合。','③ 两路特征在 temporal Transformer 中融合，随后通过向量量化 lookup 到有限 Token Vocabulary。','④ decoder 从量化表示重建被遮蔽的谱图，迫使 codebook 表示局部时间—频率 motif。','⑤ 右侧把离散 EEG token 作为下游 Transformer 的真实输入，遮蔽 token ID 后以交叉熵预测，而非退回连续 raw patch。'],visibleText:'Figure 2 的左半部训练 tokenizer，右半部训练下游 encoder。这里 tokenizer 包括时域支路、谱域支路、temporal Transformer、量化器和 decoder；codebook 只是其中保存离散 motif 向量的词表。与 LaBraM 的关键区别是，TFM token 不仅充当 masked prediction 标签，而且在下游推理时取代原始 segment embedding。单通道训练让相同词表可应用到任意通道数，再由下游模型组合通道关系。迁移到 sEMG 时应检查 token 是否跨设备稳定，同时保留连续旁路以避免角度、速度和力度被离散化抹平。'},
      mechanism:{title:'机制：时域—谱域双编码、VQ 词表与两阶段掩蔽',modules:['输入：单通道 EEG 用重叠窗口切分；并行计算原始时域 patch 与 STFT 谱窗','谱域编码：按频带切局部窗口，经频率 patch encoder、频率 Transformer 与门控聚合生成谱特征','时域编码：temporal encoder 与 temporal Transformer 捕获跨 patch 上下文','量化与重建：连续 motif 表示最近邻映射到 codebook，decoder 重建被时间/频带遮蔽的谱图','下游：多通道 token 序列加入 Transformer，随机遮蔽离散 ID，以交叉熵预测 token'],lossExplanation:'第一阶段以时频掩蔽重建和向量量化项学习 codebook；第二阶段使用离散 token 交叉熵。它不是实例对比学习，也不依赖教师网络。',visibleText:'该方法把“词表学习”和“上下文学习”明确分成两阶段。时间 mask 防止只记相邻谱窗，频带 mask 迫使模型跨频段推断；Localized Spectral Window Encoder 避免整张谱图被强低频能量支配。VQ 使相似 motif 共享 token，但引入 codebook 利用率、死码和量化误差问题。对 1 kHz sEMG，可把频带改为与肌电功率谱和运动单位活动相关的自适应子带，并在同一骨干保留连续 latent；离散分支服务动作原语和序列，连续分支服务关节角与速度。'},
      evidence:{title:'证据：四个 EEG 基准、插件式增益与跨设备耳 EEG',datasets:['四个多样 EEG benchmark，覆盖单数据集和多数据集预训练','跨设备实验使用不遵循标准 10–20 布局的 ear-EEG 睡眠分期'],metrics:['论文摘要报告 TUEV 上 Cohen’s kappa 相对强基线最高约提升 11%','作为 plug-and-play tokenizer 接入 BIOT 和 LaBraM，在 TUEV 上约提升 4%；ear-EEG 相对基线约提升 14%'],ablations:['比较连续切窗 token、不同词表/量化方案以及时间—频率双路组件','分析 token 一致性、类别特异性与频率感知结构，并评估跨设备复用'],limits:['结果以分类为主，尚未验证离散 token 对连续回归的损失','单通道词表弱化跨肌肉协同，sEMG 仍需显式空间上下文'],visibleText:'TFM-Tokenizer 的证据不只来自最终准确率：它还把 token 接入不同骨干，测试同一词表是否可作为通用接口，并在耳 EEG 上做跨设备验证。摘要给出的最高增益分别为 TUEV Cohen’s kappa 约 11%、BIOT/LaBraM 插件式约 4%、ear-EEG 约 14%，这些数字属于特定设置，不能当作平均提升。token 可视化表明词表与频率和类别结构有关，但可解释性仍是相关而非因果。对 sEMG 应增加码本利用率、跨日 token 一致性、运动学邻域保持和连续轨迹误差。'},
      transfer:{title:'迁移：离散收缩 motif 可做第二阶段，而非唯一表示',innovations:['单通道学习可跨设备复用的离散 motif 词表','时间与局部频带双路径显式建模','离散 token 在下游继续作为输入，接口真正闭环'],borrow:['用 20–100 ms 时域形态与 100–250 ms 局部谱窗联合定义 sEMG motif','将 codebook token 与连续 latent 并行，允许手势序列头和连续运动头各取所需'],avoid:['不要直接采用 EEG 频段边界或只按单通道建模，肌肉协同需要跨通道上下文','不要以 token 预测准确率代表表示质量；静息/噪声 token 可能非常容易预测'],experiments:['E1：连续 token、离散 token、连续+离散双路，统一比较手势和连续运动','E2：codebook 大小 256/1024/4096/8192，报告 perplexity、死码率、跨域一致性和量化误差','E3：时间 mask、频带 mask、双 mask 消融，并按动作相位分析 token','E4：训练设备/采样率 A，测试 B；held-out subject/day/rotation/displacement 与少样本适配'],visibleText:'建议把 TFM-Tokenizer 放在连续基线稳定之后验证。sEMG tokenizer 可先从每通道的短时波形与局部谱图提取 motif，再由跨通道 Transformer 解释肌肉协同；但连续 latent 必须保留给角度、速度和力度回归。核心判据不是码本看起来像“肌肉词汇”，而是同一 token 在跨人、跨日、旋转和设备变化后仍对应相近运动学，并且没有牺牲连续轨迹。若离散分支只提升手势而损害连续任务，最终基座应采用双路表示而不是全离散化。'}
    }
  },
  {
    id:'apple_wearable', title:'Large-scale Wearable Biosignal FM', fullTitle:'Large-scale Training of Foundation Models for Wearable Biosignals', venue:'ICLR 2024', status:'peer-reviewed', source:U.apple_wearable[0], pdfSource:U.apple_wearable[1],
    slides:{
      positioning:{title:'Apple wearable FM：用参与者级纵向一致性构造正样本',sections:['规模：AHMS 中 141,207 名 PPG 参与者与 106,643 名 ECG 参与者','数据：约 1,985 万个 60 秒 PPG 片段与 374 万个 30 秒 ECG 片段','目标：不同日期的同一参与者片段为正对，学习稳定个体生理表示'],visibleText:'该工作利用 Apple Heart and Movement Study 的多年纵向数据，分别训练 PPG 与 ECG 编码器。核心不是掩蔽重建，而是参与者级对比学习：从同一人的不同时间片段取正对，再分别施加随机裁剪、噪声、时间/幅度扭曲和通道置换。编码器与投影头采用 momentum 更新分支，损失由双向 InfoNCE 和 KoLeo 熵正则组成。其下游证明 embedding 含年龄、性别、BMI、健康状况和用药信息。对 sEMG 的重要警示是：同人正对会强化身份稳定性；若目标是运动与手势，正对必须同时控制动作语义，不能把“同一个人”直接等同“同一动作”。'},
      overviewFigure:{title:'Figure 3：同一参与者跨片段正对的动量对比框架',numberedExplanations:['① 每位参与者抽取两个不同日期或时刻的生理片段，形成 participant-level positive pair。','② 两个片段分别经过随机增强模块 T，PPG 与 ECG 使用不同强度和不同增强集合。','③ online 与 momentum 编码器把波形映射为 256 维 embedding；MLP 投影头得到 128 维对比表示。','④ 正对在表示空间被拉近，批内其他参与者构成负对并被推远。','⑤ KoLeo 正则扩大批内最近邻距离，避免 embedding 挤在低维子空间；momentum 分支提供滞后目标。'],visibleText:'Figure 3 以两名参与者、四个片段示意正负关系：同色表示同一参与者，不要求两个片段时间相邻；编码器后先得到可迁移 embedding，再经投影头进入对比空间。图中没有离散 tokenizer、codebook 或波形 decoder。对比目标显式选择了要保留的“不变量”——跨时间仍属于同一人。对于 sEMG，这种采样若原样使用会学习解剖、皮肤和设备特征；更合适的是将“同动作意图、不同日期/佩戴”的片段设为正对，并以运动学或提示标签约束，另用对抗/去相关抑制身份捷径。'},
      mechanism:{title:'机制：Regularized InfoNCE + momentum training',modules:['PPG：60 秒、四光学通道，统一到 64 Hz并逐片段 z-score；ECG：30 秒单导联，降到 128 Hz','正样本：同一参与者的两个不同片段；负样本：批内其他参与者','增强：crop、cutout、Gaussian noise、time warp、magnitude warp，PPG 另有 channel permutation','编码器：1D-EfficientNet 为主，也比较 1D-ResNet 与 1D-ViT；embedding 256 维，投影 128 维','损失：双向 InfoNCE（温度 0.04）+ KoLeo 正则（权重 0.1），online/momentum 编码器与投影头'],lossExplanation:'InfoNCE 让同一参与者跨片段表示相近、其他参与者远离；KoLeo 鼓励批内表示均匀展开。momentum 不是 BYOL 式无负样本目标，而是在仍有负样本的对比框架中增加目标滞后。',visibleText:'该方法把数据规模与正对定义放在同等位置。参与者级正对显著优于同一片段的两种增强，因为它强制模型跨越真实日期和状态变化；但模型学到的是个体生理稳定性。PPG 与 ECG 需要不同增强强度，说明增强不是模态无关的技巧。对 1 kHz sEMG 应将随机通道置换改为物理圆周旋转，将时间扭曲限制在动作可接受范围；正对最好来自同一动作/轨迹在不同佩戴和日期的重复，而不是同一人的任意片段。'},
      evidence:{title:'证据：大规模线性探测与正对/框架/增强消融',datasets:['AHMS：PPG 141,207 人、19,854,101 片段；ECG 106,643 人、3,743,679 片段','受试者级 80%/10%/10% 划分；PPG 平均每人约 92.5 个记录日，ECG 约 23.3 个记录日'],metrics:['对年龄/BMI 使用 MAE，对二分类人口学和健康问卷使用 AUC或 partial AUC；编码器冻结后线性探测','结论：PPG/ECG embedding 包含人口学与多种健康信息，PPG 在若干任务上比 ECG 更丰富'],ablations:['participant-level 正对优于 segment-level 正对','与 SimCLR、BYOL 变体比较；移除 KoLeo 后 smooth effective rank 和下游表现下降','1D-EfficientNet、ResNet、ViT 与单一增强函数比较，显示性能不依赖唯一骨干且增强具有模态特异性'],limits:['标签多为自报问卷，存在噪声与人群选择偏倚','目标主动保留个体信息，与动作不变表征的需求可能相反'],visibleText:'这项工作的强证据是受试者规模、纵向跨度和系统消融，而不是某个单一健康任务的最高分。Table 2 显示参与者级正对更利于年龄、性别和 BMI；Table 3 比较 KoLeo、SimCLR 与 BYOL，Table 4 比较不同编码器。作者也强调 InfoNCE 或 effective rank 不能直接跨模态比较，低预训练损失不保证更好下游。对 sEMG，应复现实验逻辑：比较实例级、同人任意片段、同动作跨日、同运动学跨人正对，并用身份可预测性作为副指标，避免把个体记忆误认为运动泛化。'},
      transfer:{title:'迁移：重写正对关系，学习跨佩戴的运动不变量',innovations:['真实纵向片段构成正对，不只依赖人工增强','动量对比与 KoLeo 同时控制稳定性和表示展开','大样本消融分离正对、骨干与增强贡献'],borrow:['同一动作/轨迹在不同日期、腕带旋转和位移下作为正对','使用跨受试者相同运动学邻域正对，促使表示聚焦运动结果'],avoid:['同一人的任意片段不能直接设为正对，否则身份和解剖将压过动作语义','通道随机置换不符合环形电极几何，应改为循环移位或坐标变换'],experiments:['E1：segment-level、participant-level、action-conditioned、kinematics-conditioned 四种正对策略','E2：InfoNCE、InfoNCE+KoLeo、VICReg/无负样本、教师 latent 对齐比较','E3：增强单项和组合消融，检查旋转、幅度、时间扭曲是否保持动作标签','E4：双下游 + 身份线性探测，在 held-out subject/day/rotation/device 上分析语义—身份权衡'],visibleText:'对 sEMG，最有价值的不是照搬“同人即正样本”，而是把采样单位改成运动语义。推荐以同步关节角/IMU 或动作提示寻找跨人、跨日、跨佩戴的近邻正对；同一人的不同动作应允许分离。KoLeo 可防止表示坍塌，但不能消除身份捷径，因此额外报告身份线性探测和动作条件下的域可预测性。若某种对比策略提高同人测试却降低 held-out subject 的手势与连续轨迹，应淘汰。最终目标是跨域保持动作邻域，而不是最大化参与者聚类。'}
    }
  },
  {
    id:'moment', title:'MOMENT', fullTitle:'MOMENT: A Family of Open Time-series Foundation Models', venue:'ICML 2024', status:'peer-reviewed', source:U.moment[0], pdfSource:U.moment[1],
    slides:{
      positioning:{title:'MOMENT：以统一补丁化掩蔽重建覆盖多类时序任务',sections:['语料：Time Series Pile 聚合多领域公开时序，并尽量仅纳入训练划分以降低泄漏','表示：长度 512 的单变量窗口切成不重叠 patch，经过 RevIN、线性投影与 Transformer','目标：随机遮蔽 patch 后重建原始连续值，同一编码器适配分类、预测、异常检测和插补'],visibleText:'MOMENT 是通用时序基座模型的代表，其价值不在生理先验，而在建立可复用的训练—迁移范式。每条单变量时序被规范为长度 512，经可逆实例归一化后切成固定 patch；被遮蔽的 patch 用共享 mask embedding 替换，T5 风格 encoder 从可见上下文恢复连续值。预训练没有 codebook、离散 token 或对比负样本。下游通过不同头完成长短期预测、分类、异常检测与插补，并比较零样本、线性探测与微调。对 1 kHz sEMG，它提供可靠的连续掩蔽基线，但单变量和固定长度设计会丢失腕带通道几何与多时间尺度运动信息。'},
      overviewFigure:{title:'Figure 3：patch、随机 mask、共享编码器与轻量重建头',numberedExplanations:['① 输入窗口先由 RevIN 消除样本级均值与尺度差异，并保留反归一化统计量。','② 长度 512 的时序被切成不重叠连续 patch；线性层将每个 patch 投影为连续 token。','③ 随机位置替换为可学习的 mask token，位置编码标记 token 顺序。','④ Transformer encoder 只编码一次，重建头预测被遮蔽 patch 的原始值。','⑤ 预训练后移除重建头，根据预测、分类、异常检测或插补任务连接不同输出头。'],visibleText:'Figure 3 清楚区分 patch token 与离散 token：这里的 token 只是连续向量，不对应固定码本索引。掩蔽比例和 patch 尺度决定模型需要利用多远的上下文；轻量 decoder 迫使主要信息留在 encoder 中。图中统一的 encoder 支撑多个任务，但输入仍被整理为单变量、定长 512。对高频 sEMG，应把通道作为空间轴保留，并同时设置 20–50 ms 局部 patch 与 200–500 ms 动作上下文；若简单把每个通道拆成独立样本，会切断协同收缩模式。'},
      mechanism:{title:'机制：RevIN + 连续 patch 掩蔽均方误差',modules:['预处理：单变量长度 512；RevIN 做实例归一化并可在输出端反变换','tokenizer：固定长度不重叠 patch 经线性层投影，是确定性连续 tokenizer','骨干：encoder-only Transformer，借鉴 T5 的预归一化等稳定训练设计','预训练：随机遮蔽部分 patch，轻量线性重建头恢复其连续采样值','迁移：全量微调、冻结线性探测或零样本任务头'],lossExplanation:'损失只在被遮蔽 patch 上计算连续值 MSE。它没有 VQ 码本、token 分类、对比学习或教师网络；优点是简单稳定，风险是把生理信号的高频噪声也当成重建目标。',visibleText:'MOMENT 的关键工程判断是以尽可能统一的输入和目标跨领域扩展，而不是为每个模态设计先验。RevIN 缓解量纲与偏置差异，patch 降低序列长度，随机 mask 迫使上下文推理。对 sEMG，直接波形 MSE 可能鼓励恢复噪声、工频与个体幅值，而非运动语义，因此应比较原波形、包络、频谱和 latent teacher 四种目标。连续运动需要因果或低延迟分支；原模型的双向编码只能作为离线表征基线。'},
      evidence:{title:'证据：跨任务迁移而非单一榜单',datasets:['Time Series Pile 汇集多个领域训练集，作者主动讨论公开数据的潜在预训练—测试污染','评测覆盖长/短期预测、分类、异常检测与插补，使用多个常见时序基准'],metrics:['预测与插补报告 MSE/MAE，分类报告 accuracy/F1，异常检测使用检测指标；不同任务不可简单平均','比较从头训练、监督专用模型、零样本、线性探测与全量微调'],ablations:['比较模型规模、预训练数据与不同适配方式，显示预训练并非对所有数据集都稳定领先','分析 patch、mask 和预训练对不同任务类型的作用，强调通用能力需多任务验证'],limits:['固定长度单变量接口弱化多通道同步结构和真实采样率语义','公开语料可能与下游来源相近，且波形 MSE容易学习低级可预测成分'],visibleText:'MOMENT 的贡献是把“基座模型是否通用”转化为任务族测试，而不是只做分类。其结果在多个预测、分类、异常与插补基准上具有竞争力，但不同任务和数据规模下收益并不一致，因此不能宣称统一模型必然优于专用模型。数据治理尤其重要：作者尽量只使用源数据训练划分，却仍承认公开语料污染难完全排除。sEMG 研究应实行按人、按天、按设备的严格语料登记，并把手势分类和连续轨迹回归并列为主指标。'},
      transfer:{title:'迁移：将 MOMENT 作为连续掩蔽的最低可行强基线',innovations:['统一连续 patch 接口和轻量掩蔽重建目标','同一 encoder 在预测、分类、异常和插补之间复用','显式区分零样本、线性探测和全量微调'],borrow:['以 RevIN 或稳健幅值归一化处理跨人增益差异，但保留一条幅值敏感支路','先构建多通道连续 masked autoencoder，再逐项增加 sEMG 先验'],avoid:['不要把 512 点等同于通用时间长度；在 1 kHz 下仅 512 ms','不要只报告随机窗口划分，必须按受试者和采集日隔离'],experiments:['E1：20/50/100 ms patch 与 0.4/1/2 秒上下文网格，比较双下游和延迟','E2：波形 MSE、包络重建、STFT 重建、teacher latent 对齐四种目标','E3：通道独立、早期通道融合、时空双轴注意力三种接口','E4：从头、线性探测、全微调、参数高效适配在跨人/跨日/旋转条件下比较'],visibleText:'建议把 MOMENT 风格模型设为第一条必须击败的基线：它不需要标签、实现清晰，也能验证数据规模是否有效。随后再证明 sEMG 特化设计带来额外价值，例如圆环坐标、频带目标和连续—离散双路。实验必须固定算力和参数量，避免把结构收益与规模混淆；同时报告 20–100 ms patch 对手指快速事件与连续速度平滑性的不同影响。若复杂 tokenizer 不能稳定超过连续掩蔽基线，就不应成为主模型。'}
    }
  },
  {
    id:'papagei', title:'PaPaGei', fullTitle:'PaPaGei: Open Foundation Models for Optical Physiological Signals', venue:'ICLR 2025', status:'peer-reviewed', source:U.papagei[0], pdfSource:U.papagei[1],
    slides:{
      positioning:{title:'PaPaGei：把 PPG 形态指标写进自监督目标',sections:['规模：57,641 小时、2,075 万个 10 秒 PPG 片段、13,517 名参与者','两条路线：PaPaGei-P 学参与者稳定性，PaPaGei-S 学形态语义','评测：10 个数据集、20 个分类或回归任务，强调开放模型和跨任务复用'],visibleText:'PaPaGei 针对光学脉搏波提出两种互补预训练。PaPaGei-P 延续参与者级对比：同一人的片段为正对。PaPaGei-S 则把生理形态纳入采样和辅助任务：用收缩期血管反射指数 sVRI 分箱构造形态相似正对，并通过三专家 MoE 预测 inflection point area（IPA）和 signal quality index（SQI）。骨干是约 570 万参数的 ResNet 式一维卷积网络。它说明模态知识不必写成复杂网络，也可写进正对规则和辅助标签。对 sEMG，可把 sVRI/IPA 换成 RMS、谱中值、零交叉、谱通量或同步运动学，但手工指标必须作为弱先验，不能替代动作语义。'},
      overviewFigure:{title:'Figure 1：多源 PPG、形态感知预训练与 20 个下游任务',numberedExplanations:['① VitalDB、MIMIC-III 与 MESA 等来源经过统一带通、质量过滤、标准化和重采样。','② 波形切成 10 秒片段，构成数千万规模预训练样本。','③ PaPaGei-P 按参与者形成正对；PaPaGei-S 按 sVRI 形态分箱形成正对。','④ 共享编码器还通过 MoE 辅助头预测 IPA 与 SQI，使表示关注脉搏形态和质量。','⑤ 冻结或微调 embedding，在疾病、生命体征、人口学等 20 个任务上评估。'],visibleText:'Figure 1 的核心逻辑是“开放多源数据—模态预处理—生理感知自监督—广泛下游”。模型没有离散 codebook，所谓基础表示来自对比空间和辅助回归。PaPaGei-S 的正样本不以完全相同波形为条件，而以可计算形态指标的相似性为条件，从而跨人聚合相近生理状态。这个思想很适合缺少动作标签的 sEMG：可用同步 IMU/关节角邻域或肌电形态邻域产生软正对，但必须测试这些指标是否在不同腕带位置仍与运动一致。'},
      mechanism:{title:'机制：形态分箱对比 + 三专家辅助回归',modules:['预处理：0.5–12 Hz 带通、10 秒切片、去除超过 25% 平线、z-score、重采样到 125 Hz','骨干：18 个残差卷积块的一维 ResNet，约 5.7M 参数','PaPaGei-P：同一参与者不同片段做对比正对','PaPaGei-S：sVRI 划分 8 个区间，同区间片段形成正对','辅助头：三个专家预测 IPA 与 SQI，和 sVRI 对比损失联合训练'],lossExplanation:'总目标将形态条件的对比损失与 IPA、SQI 的 MAE 辅助回归相加。MoE 位于辅助预测头，不等同于在主干每层路由 token；模型仍输出连续 embedding，没有 VQ 码本。',visibleText:'PaPaGei 把正对选择看作表征学习的核心：参与者正对偏向个体稳定属性，sVRI 正对偏向形态和血流动力学。IPA、SQI 预测让模型区分真实形态与质量伪影，MoE 为不同形态区间提供容量。迁移到 sEMG 时，可以构造“形态教师”：每窗预测 RMS、谱中值、收缩持续时间与信噪质量；更强版本使用同步运动学作为连续教师。若辅助指标受肤阻和放大增益强烈影响，应先做稳健归一化或让模型对设备域去相关。'},
      evidence:{title:'证据：多源预训练、20 项迁移与结构消融',datasets:['VitalDB 17,355 小时/5,866 人，MIMIC-III 19,990 小时/5,596 人，MESA 20,296 小时/2,055 人','总计 57,641 小时、20,751,206 个 10 秒片段、13,517 名参与者；下游来自 10 个数据集'],metrics:['20 个任务按分类 AUROC/F1 或回归 MAE/RMSE 评估；摘要报告分类平均约 +6.3%、回归约 +2.9% 的相对优势','在至少 14 个任务获得提升，但不同目标和数据集上的最佳变体不同'],ablations:['拆分 PaPaGei-P 与 PaPaGei-S，比较预训练数据源组合及 sVRI、IPA、SQI 组件','比较约 5M、35M、139M 模型，规模增大并非单调提升','分析肤色和人口学分组，检验可穿戴光学信号的偏差'],limits:['手工形态指标定义了模型关注范围，可能忽略指标之外的临床语义','多源数据预处理一致不等于设备域一致，且 PPG 的周期性与 sEMG 爆发性不同'],visibleText:'PaPaGei 的重要结论不是参数越大越好，而是数据与目标的模态匹配更关键。三种规模并未呈现单调收益，说明中等规模生理模型若目标合理可胜过盲目扩参。多源组合和组件消融支持形态先验的价值，但 20 个任务的度量不同，摘要中的平均提升不能解释为每个任务均提升。对 sEMG，需要在手势 macro-F1、连续角度/速度误差之外，额外报告跨肤色、皮下组织、腕围和信号质量分层，检查模型是否公平利用形态信息。'},
      transfer:{title:'迁移：用运动学和肌电形态构造“软语义正对”',innovations:['以可计算生理指标定义正对，而非仅使用人工增强','质量预测与生理形态预测共同约束 embedding','小型卷积骨干配合大数据，展示目标设计优先于盲目扩参'],borrow:['用 RMS、谱中值、谱通量、收缩占空比和信号质量作弱辅助目标','优先用同步关节角/速度的邻域构造跨人正对，形态指标作为补充'],avoid:['不要假设相似 RMS 就是相同动作；不同肌群与力水平可能产生同幅值','不要直接移植 PPG 的 10 秒窗口和 0.5–12 Hz 频带'],experiments:['E1：实例对比、同人对比、形态正对、运动学正对及其组合','E2：逐个移除 RMS/谱中值/质量/运动学辅助头，测双下游及跨域','E3：5M/20M/80M 参数在固定 token 数和算力下比较，绘制数据—模型曲线','E4：按信号质量、腕围、旋转角和日期分层报告泛化'],visibleText:'PaPaGei 最值得借鉴的是“把生理知识写入训练关系”。针对腕部 sEMG，优先让同步运动学决定正对：不同人、不同日期但关节角速度相近的窗口应靠近；RMS 与频谱只提供弱约束。辅助头应预测连续量而非泄漏动作类别，使无标签数据仍可使用。最终通过动作标签线性探测、连续轨迹回归、身份探测和域探测四组指标判断表示是否取得语义—不变性平衡；若形态任务提高身份识别却不提高运动，则需降低其权重。'}
    }
  },
  {
    id:'scaling_wearable', title:'Scaling Wearable FMs', fullTitle:'Scaling Wearable Foundation Models', venue:'ICLR 2025', status:'peer-reviewed', source:U.scaling_wearable[0], pdfSource:U.scaling_wearable[1],
    slides:{
      positioning:{title:'Scaling Wearable FMs：首次系统测量数据、模型与算力标度',sections:['数据：165,090 名 Fitbit Sense 2 / Pixel Watch 2 用户，约 800 万小时均衡语料','输入：26 个一分钟级传感器或派生特征，窗口为 26×300 分钟','目标：80% 随机掩蔽重建，同时评估插补、外推和活动分类'],visibleText:'该工作关注“可穿戴基座模型是否遵循标度律”。原始 PPG、加速度等先被设备处理成 26 路一分钟级特征，包括心率/HRV、运动、皮电、温度与高度信息；模型每次观察五小时窗口。作者在约 800 万小时受试者均衡数据上训练 2M、7M、110M 的 ViT 式 masked autoencoder，并扩展到约 4,000 万小时非均衡样本，系统改变数据、模型和算力。结论是损失随资源呈幂律下降但会饱和，模型变大必须配合更多数据。它对课题的数据工程与预算很有价值，但不是 1 kHz 原始生理波形模型，不能直接外推 patch、频带或延迟设计。'},
      overviewFigure:{title:'Figure 1：从多模态腕表数据到标度实验矩阵',numberedExplanations:['① Fitbit/Pixel Watch 多个传感器被整理成 26 路一分钟级时序特征。','② 每个样本覆盖 300 分钟，受试者级 80/20 划分避免同人泄漏。','③ 预训练随机遮蔽约 80% 值，由 Transformer masked autoencoder 恢复。','④ 同一框架在随机插补、时间插值、传感器插补和未来外推上评估。','⑤ 改变 token 数、参数量和训练计算，拟合 compute/data/model scaling 曲线。'],visibleText:'Figure 1 将数据管线、预训练、任务和标度分析串联。这里的“token”是每分钟多变量数值的连续 embedding，不存在离散 codebook。80% 高遮蔽迫使模型跨小时和跨传感器推断缺失值，适合强冗余慢变量；1 kHz sEMG 的局部波形更不平稳，直接使用同一比例可能丢失整个动作。对 sEMG 更合理的是时间块、通道块和短时高比例三种 mask 混合，并以可见运动上下文长度约束。'},
      mechanism:{title:'机制：高比例随机插补与受控标度实验',modules:['输入：26×300 的多变量分钟级矩阵，跨模态统一标准化','切分：132,072 名训练受试者与 33,018 名测试受试者，严格按人隔离','骨干：ViT 式 masked autoencoder，约 2M/7M/110M 三种参数规模','目标：随机遮蔽率约 0.8，以 MSE 恢复缺失数值；50k 步、批量 4096','标度：分别改变训练小时、参数量和计算量，分析饱和与最优配比'],lossExplanation:'预训练等价于多变量连续插补，MSE 对每个被遮蔽时间—传感器值计算。没有对比正对、教师网络或离散码本；标度结论以预训练/下游误差的经验拟合为依据。',visibleText:'方法的强项是把变量控制得较清楚：相同骨干族、相同目标下改变数据和参数，观察何时数据成为瓶颈、何时大模型过拟合。受试者均衡的 800 万小时与非均衡 4,000 万小时对比还揭示“更多小时”不等于“更多有效主体”。对 sEMG 应以独立受试者—天—动作覆盖量定义有效数据，并报告总采样点之外的多样性。训练目标可保持简单，但必须加入跨通道几何和高频频谱的质量控制。'},
      evidence:{title:'证据：四类重建任务与下游活动迁移的标度曲线',datasets:['165,090 名用户、约 800 万小时受试者均衡数据；附加约 4,000 万小时非均衡语料','26 路一分钟级特征、300 分钟窗口；数据来自消费级腕表长期自然使用'],metrics:['随机插补、时间插值、整传感器插补、外推以重建误差衡量；活动/运动任务使用分类指标','模型、数据和算力增加整体呈幂律改善，但在有限数据下更大模型会饱和甚至过拟合'],ablations:['2M、7M、110M 参数量；多档训练数据量与计算预算','均衡与非均衡人群数据对比，显示主体多样性影响 scaling 效率','预训练误差与不同下游收益的关联并非完全一致'],limits:['输入是分钟级派生特征而非原始高频波形，信号处理器已经注入大量先验','单一企业设备生态和自然人群偏差限制跨设备可重复性'],visibleText:'这项研究支持三条谨慎结论：增加数据、参数和计算通常有效；任何一项单独扩大都可能遇到瓶颈；预训练损失下降不保证所有下游同步改善。因为输入已经是分钟级特征，它更接近数字健康长程建模，而非神经肌肉接口。对 sEMG，论文级证据应绘制按独立人次、动作覆盖、佩戴变化和 token 数的四条曲线，并分开手势与连续任务；如果只有随机切窗增多而主体和佩戴不变，所谓规模收益可能是重复样本记忆。'},
      transfer:{title:'迁移：建立 sEMG 自己的“有效数据标度律”',innovations:['在同一可穿戴任务族中联合研究 data/model/compute scaling','把受试者均衡与原始小时数区分开','不仅做随机插补，还测试时间、通道和未来缺失'],borrow:['先固定一个 masked autoencoder 骨干，按人次、天数、动作与佩戴多样性逐层扩数据','对 5M/20M/80M 模型记录 loss、下游、吞吐和延迟'],avoid:['不要把分钟级标度指数直接引用为 1 kHz sEMG 结论','不要以总小时数替代有效独立运动事件和受试者覆盖'],experiments:['E1：固定总小时，改变受试者数与每人时长，比较跨人泛化','E2：固定 token 数，改变动作覆盖、采集日和腕带旋转多样性','E3：5M/20M/80M/200M 在三档数据量下拟合交互曲线','E4：随机 mask、时间块 mask、通道 mask、未来预测对双下游的迁移'],visibleText:'建议在项目第一年就设计标度子实验，而不是模型完成后补做。最关键自变量不是 1 kHz 带来的海量采样点，而是独立受试者、独立佩戴、动作组合和运动学覆盖。采用相同 tokenizer 与训练步数，逐步扩大这些维度，报告手势 macro-F1、连续角度 MAE/相关、身份泄漏和推理延迟。这样既能证明数据价值，也能回答顶会审稿人“性能来自结构还是更多数据”。若 20M 后收益饱和，应优先增加多样性而非盲目扩到百兆参数。'}
    }
  },
  {
    id:'sundial', title:'Sundial', fullTitle:'Sundial: A Family of Highly Capable Time Series Foundation Models', venue:'ICML 2025', status:'peer-reviewed', source:U.sundial[0], pdfSource:U.sundial[1],
    slides:{
      positioning:{title:'Sundial：用流匹配输出多种可能未来，而非单点均方预测',sections:['规模：TimeBench 汇集约 1.032 万亿时间点','骨干：连续 patch token + decoder-only Transformer，最长上下文约 2,880 点','目标：TimeFlow 以 flow matching（流匹配）学习每个未来 patch 的条件分布'],visibleText:'Sundial 是概率时序生成模型的代表。输入连续序列按 16 点 patch 化，经 decoder-only Transformer 的因果注意力编码；不同于用 MSE 输出一个均值，TimeFlow 学习从噪声到真实未来 patch 的条件向量场，可采样多个合理预测。模型在 TimeBench 的超大规模多领域数据上训练，面向零样本预测而非通用分类。对腕部 sEMG 的启示在于连续运动本来具有一对多和不确定性：相似肌电可能对应不同未来速度或力。但流匹配更适合作为“肌电条件下未来运动学”的辅助任务，不能替代表征学习的全部目标，也不能直接证明对离散手势有效。'},
      overviewFigure:{title:'Figure 2：因果 Transformer 条件化的逐 patch TimeFlow',numberedExplanations:['① 原始时序切成长度 16 的连续 patch，并经线性层形成 token。','② decoder-only Transformer 使用因果自注意力，只让当前位置访问历史上下文。','③ 每个上下文 token 条件化对应未来 patch 的概率分布，而不是输出固定值。','④ 训练时在真实 patch 与噪声之间采样路径，网络预测流速度场。','⑤ 推理时从随机噪声积分流方程，多次采样得到多条可能未来。'],visibleText:'Figure 2 表明 Sundial 没有离散 tokenizer 或 codebook；连续 patch embedding 进入因果 Transformer，TimeFlow 作为概率头建模未来。与扩散模型相比，flow matching 可以沿较直接路径学习从基础噪声到数据分布的变换；与 MSE 相比，它不会把多峰未来压成平均波形。迁移到 sEMG 时，应让条件变量包含过去肌电、腕带几何和可选历史关节状态，生成目标则是未来角度、速度或接触事件，而不是逐采样点复制高频肌电。'},
      mechanism:{title:'机制：多 patch 因果预测 + 条件流匹配',modules:['tokenizer：连续值按 16 点分块，线性 embedding；无向量量化','骨干：Pre-LN、RoPE、FlashAttention 与 KV cache 优化的 decoder-only Transformer','训练：multi-patch prediction 同时预测多个未来块，提高训练信号密度','TimeFlow：对每个未来 patch 建立条件概率流，预测路径上的速度向量','推理：从噪声初始化，通过数值积分得到一个或多个未来样本'],lossExplanation:'flow matching 在随机时间 t 上比较网络预测速度与构造路径的目标速度，以均方误差训练向量场。损失作用在分布运输速度，不是对最终未来做单点 MSE，也不是强化学习。',visibleText:'Sundial 的技术核心是把 Transformer 的上下文表示与连续生成头解耦。因果骨干可流式缓存，TimeFlow 捕获异方差和多峰不确定性。对 1 kHz sEMG，若直接预测未来原始波形，模型会耗费容量生成随机运动单位放电；更有意义的是下采样后的运动学、力或动作事件分布。预训练可采用双头：双向 masked encoder 学表征，因果 flow head 学可控未来；在线系统只保留因果路径，离线表示则使用更完整上下文。'},
      evidence:{title:'证据：零样本概率预测、生成目标消融与规模曲线',datasets:['TimeBench 含约 1.032 万亿时间点的多领域序列，训练语料以中低频预测数据为主','零样本评测覆盖 TSLib、GIFT-Eval 与 FEV 等多套预测集合'],metrics:['确定性指标使用 MSE/MAE，概率预测使用 CRPS、MASE、WQL 等','Table 7 中 TimeFlow 相比 diffusion/MSE 头总体取得更优 CRPS，尤其在 GIFT 任务族'],ablations:['比较 TimeFlow、扩散和 MSE 预测头，区分分布建模与单点预测','考察模型/数据规模以及多 patch 预测，显示零样本误差随规模改善','跨基准比较点预测与概率指标，避免只看一个排行榜'],limits:['TimeBench 主要不是高频生理信号，标度结论不能直接迁移到 1 kHz sEMG','生成模型可能产生看似合理但生理错误的未来，需要约束和校准'],visibleText:'Sundial 的证据集中在零样本预测：它在多个公共套件上与统计、深度和大模型基线比较，并以 CRPS 等概率指标体现多样性与校准。TimeFlow 相对 MSE 的优势说明复杂未来不宜只预测均值，但效果依数据集而异。论文也提示时序生成存在幻觉风险。对 sEMG，必须报告关节限位、速度连续性、肌电—运动时延一致性和置信区间覆盖率；若采样轨迹违反生物力学，即使 CRPS 好也不适合交互控制。'},
      transfer:{title:'迁移：把流匹配限定为连续交互的概率辅助头',innovations:['以流匹配建模多峰未来，避免均值化','因果 decoder 与 KV cache 支持流式上下文','多 patch 预测提高长程训练效率'],borrow:['以 sEMG 表征条件化未来 100–500 ms 关节角/速度分布','输出分位区间或多条轨迹，供控制器按风险选择'],avoid:['不要生成原始高频肌电作为唯一预训练目标','不要用概率指标替代实时延迟、稳定性和生物力学有效性'],experiments:['E1：MSE、Gaussian NLL、diffusion、TimeFlow 四种运动学头，固定 encoder','E2：预测 50/100/250/500 ms，比较误差、CRPS、覆盖率与控制延迟','E3：无历史姿态、含历史姿态、含 IMU 条件，测试肌电增量贡献','E4：手势分类头与 flow 回归头联合训练，验证多任务是否互利'],visibleText:'Sundial 对本项目的角色应明确：它不是主干模板，而是连续运动解码的生成式分支。先由多尺度 sEMG encoder 学稳定表示，再用轻量 TimeFlow 预测未来关节角或速度；离散手势继续使用分类/序列头。实验要与 Gaussian NLL 和普通 MSE 在相同参数量下比较，并做不确定性校准。若流匹配只改善离线 CRPS却显著增加端侧延迟，应作为服务器端研究头而非产品默认头。'}
    }
  },
  {
    id:'m2ae', title:'M2AE Biosignal Fingerprinting', fullTitle:'Biosignal Fingerprinting: A Cross-Modal PPG-ECG Foundation Model', venue:'arXiv 2026', status:'preprint', source:U.m2ae[0], pdfSource:U.m2ae[1],
    slides:{
      positioning:{title:'M2AE：以 ECG–PPG 配对学习共享 biosignal fingerprint',sections:['状态：2026 年 arXiv 预印本，结论需按非同行评审证据解读','数据：约 341 万对 10 秒 ECG–PPG，来自 MIMIC-III Waveform 与 VitalDB','目标：互补掩蔽重建 + 多集合跨模态对比，兼顾共享状态和模态私有信息'],visibleText:'M2AE 针对同步 ECG 与 PPG 提出跨模态 masked autoencoder。两路信号各重采样为 2,048 点、切成 64 点 patch，经模态专属 encoder 后进入共享 bottleneck“biosignal fingerprint”，再由双 decoder 重建。ECG 与 PPG 的 mask 比例互补，使一模态缺失信息可由另一模态补充；多集合对比把同一时刻、增强视图及扩展的同人跨时段表示拉近。论文在跨模态重建、心血管、结局和人口学任务上验证。对 sEMG，最相关的是联合 IMU/运动学预训练及缺失模态鲁棒性，但目前是预印本，且 ECG–PPG 强耦合不等于 sEMG–运动学同步关系。'},
      overviewFigure:{title:'Figure 1：双模态 encoder、共享 fingerprint 与双 decoder',numberedExplanations:['① 同步 10 秒 ECG 与 PPG 分别切 patch，并采用互补比例 mask。','② 两个模态专属 encoder 学习各自局部形态，减少早期强制共享。','③ 可见 token 在共享 bottleneck 交互，形成跨模态 biosignal fingerprint。','④ 两个 decoder 分别恢复被遮蔽 ECG 与 PPG，实现同模态和跨模态补全。','⑤ 共享表示再用于跨模态重建、疾病、结局与人口学下游任务。'],visibleText:'Figure 1 的 A/B/C 部分依次呈现总体管线、互补掩蔽与多集合对比关系。该模型的 token 是连续 patch embedding，没有离散 codebook。共享瓶颈意图捕获两个模态共同的心血管状态，而专属 encoder/decoder保留波形特性。迁移到前臂系统时，可将 sEMG 与 IMU、手指关节角或视频伪标签视为配对模态：训练期借助高质量运动学，部署期只保留 sEMG encoder，从而实现 privileged-information 预训练。'},
      mechanism:{title:'机制：互补 mask、联合重建与 multi-set 对比',modules:['输入：ECG/PPG 均统一到 2,048 点，patch size 64；按受试者划分 80/10/10','编码：模态专属 encoder + 共享 bottleneck + 模态专属 decoder','互补掩蔽：两模态 mask ratio 之和为 1，鼓励信息跨模态补偿','重建：各 decoder 预测被遮蔽的本模态连续 patch','对比：同一样本的 ECG、PPG 与增强视图为多正样本，并扩展同人跨时间正对'],lossExplanation:'总损失为双模态 masked reconstruction 与 multi-set contrastive 的加权和，论文设置温度约 0.1、两项权重同量级。没有离散码本；所谓 fingerprint 是共享连续 latent。',visibleText:'互补 mask 是方法中最可迁移的设计：当 ECG 被遮蔽较多时 PPG 保留较多，迫使共享层利用跨模态线索。多集合对比允许一个 anchor 同时对应多个正样本，弱化单一增强偶然性。对 sEMG–运动学，不能重建“未来不可知”的运动学细节，应对齐同步或考虑电生理领先运动的时延窗口。训练时还要随机整模态缺失，确保部署只输入 sEMG 时性能不崩溃。'},
      evidence:{title:'证据：跨模态重建、下游迁移与训练策略反例',datasets:['约 341 万对同步 10 秒 ECG–PPG，来自 MIMIC-III Waveform Database 与 VitalDB','按受试者 80/10/10 切分，下游覆盖跨模态重建、CVD、结局与人口学预测'],metrics:['波形重建使用误差/相似性指标，下游分类报告 AUROC 等；不同任务分别解读','联合预训练在多项跨模态与下游任务优于单模态或部分目标基线'],ablations:['比较单模态、联合重建、增加跨模态对比和扩展正对集合','单模态 warm-start 后再跨模态训练反而弱于从头联合训练，提示优化路径关键','测试缺失模态和跨模态重建能力，验证共享 bottleneck 的作用'],limits:['目前仅为预印本，尚未经正式同行评审','基础语料与若干下游可能来源相关，作者讨论了潜在重叠和公平比较问题'],visibleText:'M2AE 的有价值发现是“先单模态、后跨模态”并不一定更好：联合目标从头训练可让共享空间早期形成，而 warm-start 可能锁定模态私有局部最优。结果还展示跨模态恢复和多类下游收益，但必须牢记数据源重叠及预印本状态。对 sEMG，证据链应包含训练期有 IMU/姿态、测试期只用 sEMG的消融；同时比较早期融合、后期对齐、共享 bottleneck 与 teacher distillation，避免把更多输入带来的优势误称为单模态基座泛化。'},
      transfer:{title:'迁移：训练期多模态，部署期 sEMG-only',innovations:['互补掩蔽制造跨模态信息需求','专属编码与共享 bottleneck 平衡私有和公共信息','multi-set 对比允许同步、增强和跨时段多个正样本'],borrow:['sEMG 与 IMU/关节角/视频姿态同步预训练，部署时丢弃辅助模态','加入整模态 dropout 和时间偏移建模，提升传感器缺失鲁棒性'],avoid:['不要假设同步即同义；肌电领先运动且受电机械延迟影响','不要把预印本结果表述为已确立的最优结论'],experiments:['E1：sEMG-only、早期融合、共享 bottleneck、teacher distillation 四种预训练','E2：0/30/60/100 ms 对齐偏移，寻找动作和被试依赖的最佳窗口','E3：训练时 0–100% 辅助模态 dropout，测试严格 sEMG-only','E4：跨设备/跨日双下游，并报告辅助模态可用与不可用两套结果'],visibleText:'本项目可把 M2AE 转化为“特权模态预训练”：采集阶段使用高精度手部姿态和 IMU，迫使 sEMG latent 与运动结果对齐；部署阶段只运行腕带。共享瓶颈应同时保留连续表示和可选离散 motif，互补 mask 用来防止任一模态独占。最关键的审稿证据是：在测试不提供运动学时，预训练仍提升跨人手势和连续轨迹，并且对时间错位、IMU 缺失和腕带旋转稳健。还应按左右腕、动作速度和肌电领先量分层校准，验证共享表征是否保留真实电机械因果顺序，而非只记住同步采集批次。'}
    }
  },
  {
    id:'generic_neuromotor', title:'Generic Neuromotor Interface', fullTitle:'A generic non-invasive neuromotor interface for human-computer interaction', venue:'Nature 2025', status:'peer-reviewed', source:U.generic_neuromotor[0], pdfSource:U.generic_neuromotor[1],
    slides:{
      positioning:{title:'Nature 通用神经运动接口：人口规模 sEMG 监督学习验证通用性',sections:['硬件：腕部 48 个电极针形成 16 个双极通道，2 kHz、12-bit、20–850 Hz','任务：连续腕部控制、9 类离散手势和手写输入','规模：不同任务覆盖 162–6,627 名参与者，并测试实时闭环与个性化'],visibleText:'这项工作是当前腕部 sEMG 通用交互的重要系统证据。研究团队使用高密度一致硬件和大规模采集，训练面向人群的监督式解码器，在未见用户上完成连续腕部速度、离散手势和手写识别，并进行闭环交互。它不是自监督基座模型：各任务仍有专用网络、标签与输出头；但数据规模曲线显示参与者数和模型容量增加可持续提升泛化，个性化只需较少新用户数据即可进一步改善。对本项目，它定义了必须覆盖的任务、严格 held-out user 评测、实时指标与硬件质量上限，也是“预训练必须胜过强监督人口模型”的参照。'},
      overviewFigure:{title:'Fig. 1：腕带硬件、采集平台、任务提示与原始 sEMG',numberedExplanations:['① 研究腕带以 48 个干电极针围绕腕部接触皮肤，组合成 16 个双极通道。','② 前端以 2 kHz、12-bit 采样，并进行 20–850 Hz 硬件带通，保留高频肌电形态。','③ 统一软件平台呈现手势、腕部运动或文字提示，并同步收集标签。','④ 图中展示动作相关的多通道爆发，说明空间分布与时间形态共同承载意图。','⑤ 数据进入任务专用解码器，再在离线和实时闭环中评价。'],visibleText:'Fig. 1 首先是一张系统图，而非基座模型结构图：它强调高通量采集需要硬件、提示、时间同步、信号质量与数据基础设施共同设计。腕带左右手镜像佩戴，电极相对生理位置保持一致但极性相反，这一细节提示通道几何和极性增强必须物理合理。图中没有 tokenizer、codebook 或自监督目标。对我们的研究，最直接的借鉴是先保证 1 kHz 多通道数据、动作/运动学标签和佩戴元数据一致，再讨论复杂预训练。'},
      mechanism:{title:'机制：任务专用人口模型 + 数据/参数规模化',modules:['采集：统一 sEMG-RD 硬件与任务 prompter，支持上千参与者反复佩戴','连续控制：从多通道窗口回归腕部速度或方向，并用于闭环目标获取','离散手势：1D convolution 前端、三层 LSTM 与分类头进行流式识别','手写：连续 sEMG 转换为字符序列，结合序列模型和语言约束','个性化：在人群模型基础上使用少量目标用户数据微调'],lossExplanation:'论文主要使用监督式任务损失，按任务训练专用解码器；不存在统一的自监督预训练损失、离散码本或跨任务共享 decoder。它证明的是 population scaling 和 generic interface，而非 foundation pretraining。',visibleText:'系统把大规模跨人数据直接用于监督学习，并通过参数量—参与者数曲线展示性能随规模提高。连续、离散和手写输出的结构不同，因此“generic”指对新用户可用的接口和人群模型，不代表一个 encoder 已在所有任务间共享。这个区分十分重要：本项目的创新应在相同硬件和数据划分下证明一个预训练 encoder 能通过轻量头同时服务手势与连续运动，并降低每任务标注和个性化成本。'},
      evidence:{title:'证据：跨人开放环、实时闭环与个性化三层验证',datasets:['按任务使用 162–6,627 名参与者的大规模腕部 sEMG；统一硬件但包含真实重复佩戴','任务覆盖连续腕部控制、9 种离散手势和手写，既有离线也有闭环实验'],metrics:['held-out user 开放环：手势/手写分类超过 90%，腕部速度误差低于约 13 deg/s','闭环中位表现：连续目标获取约 0.66 次/秒、离散检测约 0.88 次/秒、手写约 20.9 WPM','在约 6,400 人基础模型上用 20 分钟个性化，手写错误率进一步改善约 16%'],ablations:['参与者数量与参数规模呈经验幂律关系，单用户模型不能直接泛化到陌生用户','比较通用人群模型和个性化适配，量化少量目标数据价值','同时报告离线和交互指标，揭示静态准确率与可用性差异'],limits:['硬件、数据和部分系统细节具有产品级门槛，外部团队难完全复现同等规模','监督标签丰富，不能回答无标签预训练是否能降低采集成本'],visibleText:'该工作的说服力来自证据层次完整：大规模 held-out user 离线结果证明跨人泛化，闭环实验验证时延与反馈下的可用性，个性化曲线说明基础人群模型能被少量数据改进。参与者和参数规模曲线也证明单用户小样本不是通用接口的充分条件。但论文未提供统一自监督 encoder 的跨任务复用证据。我们的比较应严格匹配其用户划分和在线约束，而不能只在随机切窗上报告更高准确率。'},
      transfer:{title:'迁移：把它作为系统上限与评测合同，而非预训练模板',innovations:['人口规模统一腕带采集与真实多任务闭环验证','将离线泛化、在线交互和个性化放进同一证据链','用数据与模型规模曲线支撑通用用户能力'],borrow:['沿用 held-out user、重复佩戴、开放环+闭环+个性化三级评测','保留 1 kHz 原始波形和腕带几何元数据，构建统一 encoder 多头任务'],avoid:['不要把多个监督模型称为自监督基座模型','不要只比较论文中的最终数字而忽略设备、带宽和标签规模差异'],experiments:['E1：强监督人群模型、单任务预训练、多任务共享预训练在相同数据量比较','E2：跨人、跨日、22.5°–90° 旋转、轴向位移与设备迁移矩阵','E3：0/1/5/20 分钟个性化曲线，报告参数高效适配和灾难遗忘','E4：离线 macro-F1/轨迹误差 + 在线吞吐、误触、目标获取率和端到端延迟'],visibleText:'这篇 Nature 工作应成为本项目的评测地基。模型创新必须回答三件事：在同样参与者规模下是否优于强监督专用模型；是否用更少标签达到相同 held-out user 性能；是否在实时闭环中保留收益。推荐共享一个因果 sEMG encoder，上接手势事件头和连续运动头，并预留手写序列任务。若结果只在离线随机窗口成立，就不足以声称通用神经运动接口；跨人、重复佩戴和闭环才是关键。'}
    }
  },
  {
    id:'emg2pose', title:'emg2pose', fullTitle:'emg2pose: A Large and Diverse Benchmark for Surface Electromyographic Hand Pose Estimation', venue:'NeurIPS 2024 Datasets and Benchmarks', status:'dataset-benchmark', source:U.emg2pose[0], pdfSource:U.emg2pose[1],
    slides:{
      positioning:{title:'emg2pose：370 小时腕部 sEMG 到连续手部姿态的公开基准',sections:['数据：193 名用户、751 次 session、370.3 小时、约 8,000 万帧','硬件：16 通道腕带、超过 2 kHz sEMG，同步 26 相机动作捕捉','任务：连续关节角估计，并严格区分未见用户、未见 stage 与二者同时未见'],visibleText:'emg2pose 是连续运动解码最重要的开放数据资源之一。参与者佩戴 16 通道腕带并完成 29 类 stage 中的多种手势序列，动作捕捉系统同步产生手部关节角。数据以用户、动作 stage 和二者组合构造独立测试集，避免只测试已见动作或已见人。论文提供因果基线 vemg2pose：时域卷积把 2 kHz 信号降至 50 Hz，再由自回归 LSTM 预测关节角速度并积分成姿态。它本身不是自监督基座模型，而是验证连续任务、跨域拆分和数据质量的标准场；对于我们的基座，最重要的是把它作为预训练迁移与端到端监督的公平比较。'},
      overviewFigure:{title:'Figure 2：设备、stage 层次、用户与 370 小时数据组成',numberedExplanations:['① 16 通道 sEMG-RD 腕带与动作捕捉标记同时佩戴，保证肌电—姿态同步。','② 用户按照提示完成 counting 等 movement types，多种动作组成一个 stage。','③ 共设计 29 个 stage，并在 stage 层面划分训练、验证与测试。','④ 193 名参与者多次穿脱腕带完成不同 stage，产生真实佩戴变化。','⑤ 用户轴与 stage 轴交叉形成 seen/unseen 组合，用于检验跨人和跨动作泛化。'],visibleText:'Figure 2 的重点不是网络，而是数据分解方式：movement type 嵌套在 stage 中，用户跨 session 反复佩戴，测试可以同时沿用户和 stage 外推。数据总量 370.3 小时、751 个 session、约 8,000 万帧；逆运动学约有 12.7% 帧失败，提醒标签并非绝对真值。对基座预训练，应只用训练用户/训练 stage 的无标签波形学习，在下游测试严格隔离；若把测试动作的无标签数据提前用于预训练，必须明确标为 transductive 设置。'},
      mechanism:{title:'基线：因果 TDS 降采样 + 自回归速度积分',modules:['输入：16 通道 >2 kHz 腕部 sEMG，预处理后流式进入网络','前端：causal strided time-depth separable convolution 将 2 kHz 压到约 50 Hz','状态：把上一时刻预测的关节角与肌电特征拼接','序列：自回归 LSTM 预测下一步关节角速度','输出：积分速度得到连续姿态；训练同时约束关节角和指尖位置'],lossExplanation:'基线损失为关节角 L1 与约 0.01 权重的指尖欧氏距离之和。没有自监督预训练、掩蔽重建、对比学习或 codebook；它是有标签因果回归器。',visibleText:'vemg2pose 通过预测速度再积分引入平滑连续性，并使用上一姿态降低瞬时肌电歧义。因果卷积和 50 Hz 输出使其接近在线控制需求，但自回归会累积漂移，也可能过度依赖历史姿态。对预训练 encoder 的公平接入方式是替换 TDS 前端而保持 LSTM 与损失不变，或同时比较仅肌电和肌电+历史姿态。这样才能区分表示收益与更强 decoder 的收益。还应报告肌电相对姿态的电机械延迟扫描。'},
      evidence:{title:'证据：四种泛化划分与角度/指尖双指标',datasets:['总计 193 人、370.3 小时、751 sessions、29 stages、约 80M 帧','训练：158 人约 250.9 小时；held-out user 20 人约 31.9 小时；另有 held-out stage 与组合测试'],metrics:['held-out user：约 12.2° 平均关节角误差、15.8 mm 指尖误差','held-out stage：约 15.2°/20.4 mm；held-out user+stage：约 15.8°/21.6 mm','同时提供每关节、动作与数据质量分析，最困难组合明显退化'],ablations:['比较简单基线与自回归 vemg2pose，后者利用历史姿态和速度输出','四种 split 分离人物、动作语义及其叠加的难度','分析逆运动学失败与不同 stage 数据分布，揭示标签噪声'],limits:['动作捕捉/逆运动学有约 12.7% 失败帧，连续标签存在缺失和误差','腕带硬件和特定采集提示限制向其他设备及自然环境外推'],visibleText:'该基准最有价值的结论是“未见人”和“未见动作”不是同一问题：当两者同时变化，角度和指尖误差进一步升高。Table 4 的 12.2°/15.8 mm、15.2°/20.4 mm 与 15.8°/21.6 mm 提供了可复现锚点，但数字依赖关节集合、后处理和设备，不能跨论文直接排名。对基座模型，应沿用四象限拆分并加入跨日、旋转和轴向位移；若预训练只改善 seen-stage，不足以证明学到通用运动表征。'},
      transfer:{title:'迁移：作为连续运动主战场与严格数据合同',innovations:['大规模公开同步 sEMG—手姿态资源','用户×stage 正交划分揭示不同泛化来源','因果自回归基线连接离线评测与在线潜力'],borrow:['把连续关节角/速度设为与手势分类同等重要的主下游','使用训练 split 无标签预训练，冻结/微调并接同一 vemg2pose 头'],avoid:['不要随机按窗口拆分，否则同人同 session 泄漏严重','不要只报告平均角度误差，指尖与快速动作可能被平均掩盖'],experiments:['E1：从头、连续 masked、对比、混合预训练在四种 split 上统一比较','E2：仅 sEMG 与加入历史姿态，测表示的独立贡献和漂移','E3：20/50/100 Hz 输出频率与 50–300 ms 上下文，比较精度—延迟','E4：每关节、每 stage、收缩强度和 IK 质量分层，并做少样本适配'],visibleText:'建议将 emg2pose 设为连续运动的主要公开验证集。预训练阶段严格不接触测试用户和测试 stage；下游保持相同 decoder、参数量和训练预算，比较随机初始化、MOMENT 式掩蔽、AEMG 式离散词表和多目标方案。除了角度与指尖误差，还报告相关系数、速度误差、漂移、实时因果延迟及快速手指动作。若方法在 user+stage 组合上仍有稳定收益，才能说明表示超越动作模板记忆。'}
    }
  },
  {
    id:'emg2qwerty', title:'emg2qwerty', fullTitle:'emg2qwerty: A Large Dataset with Baselines for Touch Typing using Surface Electromyography', venue:'NeurIPS 2024 Datasets and Benchmarks', status:'dataset-benchmark', source:U.emg2qwerty[0], pdfSource:U.emg2qwerty[1],
    slides:{
      positioning:{title:'emg2qwerty：346 小时双腕 sEMG 到真实键盘字符序列',sections:['数据：108 名参与者、1,135 sessions、346.4 小时，平均约 4.4 字符/秒','硬件：左右腕各 16 通道，共 32 通道、2 kHz、12-bit、20–850 Hz','任务：CTC 序列识别 + 语言模型，重点测人群模型和少量个性化'],visibleText:'emg2qwerty 把腕部 sEMG 从孤立手势推进到高速自然序列。受试者真实触碰 QWERTY 键盘，双腕各 16 通道信号与按键时间同步；100 名用于通用训练，8 名保留做个性化评测。基线用频谱特征、rotation-invariance 模块和 TDS ConvNet 输出字符概率，经 CTC 对齐未知边界，再由支持退格的六元字符语言模型束搜索解码。通用模型字符错误率仍约 51.78%，而目标用户微调可降到 6.95%，说明快速细粒度手指意图高度个体化。这是序列交互和适配研究的重要基准，但语言模型会掩盖肌电表示强弱，必须分开报告声学式 sEMG encoder 与解码约束。'},
      overviewFigure:{title:'Figure 1：双腕 32 通道波形、按键时间与镜像电极布局',numberedExplanations:['① 左右腕带各含 16 个双极通道，总计 32 路，以 2 kHz 同步记录。','② 图中竖线标记真实按键发生时刻，连续波形在快速字符间没有人工切段。','③ 研究腕带的电极环绕腕部，对左右手采用镜像佩戴以对齐生理位置。','④ 镜像会导致相对极性反转，因此模型或预处理必须显式处理。','⑤ 原始高通波形与键盘 keylogger 共同构成 CTC 所需的连续序列监督。'],visibleText:'Figure 1 直观展示连续打字的难点：字符间隔短、左右手交替、肌电爆发重叠，标签只有离散按键时间而没有每帧动作边界。腕带镜像保持电极相对生理位置，但信号极性反转，说明通道旋转和符号翻转可构成有物理依据的增强。图中同样没有自监督 tokenizer 或 codebook。对基座预训练，双腕同步是一种天然多视图；但左右手并非总做同一动作，不能简单作为正对，应利用按键、手别和时间上下文约束。'},
      mechanism:{title:'基线：谱图 TDS ConvNet + CTC + 6-gram 语言模型',modules:['输入：双腕 32 通道连续 sEMG，以短时频谱特征增强稳定性','空间鲁棒：rotation-invariance 模块处理腕带圆周旋转','骨干：TDS ConvNet 以约 1 秒感受野生成逐帧字符分布','对齐：CTC 引入 blank，边际化未知字符边界和重复路径','解码：backspace-aware 6-gram 字符语言模型 + beam search'],lossExplanation:'训练使用 CTC 负对数似然；字符语言模型仅在解码时重排序候选。没有自监督掩蔽、对比或离散码本。LM 的先验收益必须与纯 sEMG logits 分开报告。',visibleText:'CTC 适合连续肌电，因为动作边界未知且字符序列比帧短。TDS 卷积在时间—通道上高效建模，rotation module 将环形电极移位纳入网络不变性。语言模型显著利用英语拼写和键盘先验，因此低 CER 不完全来自神经肌肉解码。对通用基座而言，可先用无标签双腕序列做 masked/预测预训练，再固定同一 CTC 头；另外以无 LM、同一 LM 和 oracle 约束三档评测分离表示、序列头和语言知识。'},
      evidence:{title:'证据：通用模型与个性化之间的巨大差距',datasets:['108 人、1,135 sessions、346.4 小时；94/108 人至少有 2 小时数据','100 人训练通用模型；8 人每人保留 2 个验证和 2 个测试 session 做个性化'],metrics:['通用模型 + LM 字符错误率约 51.78%','目标用户从头训练 + LM 约 9.55%；从通用模型微调 + LM 约 6.95%，最佳用户约 3.16%','同时比较无语言模型和不同数据量，显示个体数据与文本先验贡献'],ablations:['rotation-invariance、频谱输入、语言模型与个性化初始化分别比较','按个性化分钟/小时绘制学习曲线，通用初始化显著提高样本效率','严格按参与者和 session 划分，避免相邻打字片段泄漏'],limits:['英语触摸打字和物理键盘限制到其他语言、键盘布局与空中手势的泛化','LM 可修正生理误判，若只报告最终 CER 会高估 encoder 能力'],visibleText:'该论文最醒目的证据是 51.78% 到 6.95% 的差距：通用跨人打字仍困难，但人群预训练为个性化提供良好初始化。最佳用户 3.16% 说明腕部肌电含足够丰富的细指运动信息；同时，目标用户从头训练 9.55% 表明数据量和个体结构非常关键。所有数字均含指定语言模型，评价基座时必须补充无 LM CER、帧级边界与按键召回，否则不能判断提升来自肌电表征还是更强文本先验。'},
      transfer:{title:'迁移：用连续序列检验 token 是否保留快速手指语义',innovations:['双腕高频连续自然交互数据，而非切好的孤立手势','CTC 处理弱边界标签，rotation module编码环形几何','通用初始化显著降低个性化数据需求'],borrow:['把字符或手势事件建成流式序列头，检验长上下文与快速边界','使用循环通道移位、左右镜像和极性翻转等物理增强'],avoid:['不要依赖 LM 后的 CER 作为唯一预训练指标','不要把左右腕同步窗口无条件设为对比正样本'],experiments:['E1：相同 CTC 头下比较从头、连续 masked、离散 token、混合预训练','E2：0/1/5/20/60 分钟个性化，画 CER 与遗忘曲线','E3：无 LM、固定 6-gram、神经 LM 三档解码，分离 encoder 贡献','E4：旋转、镜像、单腕缺失、键盘布局和输入速度分层测试'],visibleText:'emg2qwerty 可作为手势分类之外的高难序列任务：它要求表示同时保留毫秒级爆发、左右手协调和秒级上下文。若离散 codebook 真捕获“运动基元”，应在低标注 CTC 和个性化时提升，而不只改善孤立手势。实验必须固定 LM、beam 和 decoder，只替换 encoder；同时报告无 LM 结果和事件级时延。这样才能证明预训练学到快速手指意图，而非利用语言纠错。'}
    }
  },
  {
    id:'aemg', title:'AEMG', fullTitle:'Reading Your Actions: Learning Generalizable Action Representations via Pre-training AEMG', venue:'CVPR 2026', status:'peer-reviewed', source:U.aemg[0], pdfSource:U.aemg[1],
    slides:{
      positioning:{title:'AEMG：跨数据集 EMG 离散动作词表与 masked token 预训练',sections:['数据：8 个异构 EMG 数据集、超过 500 person-time，面向跨设备和跨布局','两阶段：Neural Contraction Tokenizer（NCT）生成动作 token，NST 预测被遮蔽 token','评测：4 个 LOSO 数据集零样本/少样本动作识别，CVPR 2026 同行评审'],visibleText:'AEMG 是与本课题最直接相关的预训练方法。它先用能量阈值和滑窗定位肌肉收缩片段，经一维卷积编码、固定通道拓扑映射及补齐/截断形成标准表示，再通过 VQ codebook 将收缩量化为 8,192 个 canonical motor primitive。第二阶段 Neural Signal Transformer（NST）加入空间、时间和位置 embedding，随机遮蔽多个 patch，并预测相应离散 token ID。作者在 8 个异构数据集上预训练，在 ULB-MLG、EMG-EPN、Ninapro DB4 和 Toro-Ossaba 做 leave-one-subject-out，报告零样本提升 5.79–9.25 个百分点、5% 少样本达到完整监督 90% 以上相对性能。它证明离散 EMG 词表可行，但下游以分类为主，连续运动保真仍未回答。'},
      overviewFigure:{title:'Figure 2：NCT 码本学习与 NST 跨 patch 掩蔽预测',numberedExplanations:['① 原始异构 EMG 经能量阈值滑窗提取 contraction，减少静息和长度差异。','② 一维卷积提取局部形态，通道被映射到固定拓扑并补齐/截断。','③ VQ codebook 含 8,192 个向量；最近邻索引把连续 contraction 变为 canonical token。','④ NST 为 token 加空间、时间和位置 embedding，以 Transformer 建模跨肌肉协同。','⑤ 跨 patch mask 后，模型预测被隐藏位置的 token ID，实现离散 masked modeling。'],visibleText:'Figure 2 必须分清三个概念：NCT 是完整 tokenizer 管线，负责切 contraction、编码和量化；codebook 只是其中 8,192 个可学习向量的集合；token 是一次输入被映射到某个 code 后得到的索引或 embedding。第二阶段 NST 不再重建原始波形，而以分类方式预测被遮蔽的离散 motor primitive。图中固定拓扑映射解决通道数量和布局不一致，但标准化过程也可能丢失真实腕带圆环几何。'},
      mechanism:{title:'机制：收缩感知量化 + 跨 patch token 分类',modules:['NCT 分割：按能量阈值在滑窗中提取 contraction，避免固定切片大量包含静息','连续编码：1D convolution 提取波形形态，通道布局映射到固定 topology','VQ：8,192 大小 codebook，以最近邻产生离散 token，并通过重建、词表与 commitment 损失训练','NST：空间、时间、位置 embedding + Transformer，建模 token 之间关系','预训练：跨 patch mask，分类预测一组被遮蔽 token ID'],lossExplanation:'第一阶段包含信号重建、codebook 更新和 commitment 项，使 encoder 输出靠近选中码向量；第二阶段对被 mask 的离散 token 做交叉熵。它不同于连续 MSE，也不需要对比负样本。',visibleText:'AEMG 的设计将“什么是 token”先固定为收缩基元，再学习基元之间的上下文。NCT 的能量切分减少无效静息，但阈值对电极增益和细微手指动作敏感；8,192 码规模提高容量，也可能产生死码和设备专属码。NST 的跨 patch 预测可学习动作组合。对连续回归，硬量化会舍弃幅值与细相位，因此建议保留连续 latent 旁路，形成 discrete motif + continuous dynamics 的双路 encoder。'},
      evidence:{title:'证据：LOSO、少样本、切分与词表消融',datasets:['8 个异构 EMG 数据集，累计超过 500 person-time；设备、通道与动作集合不同','4 个 LOSO 下游：ULB-MLG、EMG-EPN、Ninapro DB4、Toro-Ossaba'],metrics:['摘要报告零样本 LOSO 相对六种基线提升约 5.79–9.25 个百分点','使用 5% 标签微调可达到完整训练 90% 以上的相对性能；示例 ULB 88.50、Ninapro 85.18','Table 3：NCT 平均约 91.28，固定切片约 82.15，差约 9.13'],ablations:['移除 vocabulary 在部分数据集下降约 28.3/25.5，移除 masked pretraining 约下降 10.2','比较能量 contraction tokenization 与固定窗口，支持自适应分段','分析少样本比例和异构数据组合，验证预训练对标签效率的贡献'],limits:['核心结果仍是离散动作分类，未验证连续角度、速度和力回归','能量阈值、固定拓扑和大码本可能编码设备/幅值捷径，需跨日与位移审计'],visibleText:'AEMG 的消融较有力：收缩感知 tokenization 相比固定切片平均提高约 9.13 个点，移除词表或 masked pretraining 出现明显退化，说明收益不只来自更大 Transformer。零样本和 5% 少样本结果切合基座模型主张。但“零样本”仍位于既定动作标签空间，不能等同开放词汇动作理解；而且没有连续运动指标。我们的复现需检查 codebook perplexity、死码率、码与设备/受试者互信息，并在 emg2pose 上测硬量化造成的信息损失。'},
      transfer:{title:'迁移：以 AEMG 为直接基线，发展连续—离散双路基座',innovations:['收缩感知自适应 tokenization 处理异构长度和静息','VQ codebook 构造跨数据集 motor primitive 词表','masked token prediction 提供标签高效动作表示'],borrow:['复现 NCT+NST 作为离散强基线，并加入圆环电极坐标和 1 kHz 多尺度切片','保留连续 latent 分支，与离散 token 在高层交互'],avoid:['不要只按高能阈值取 contraction，低幅精细指动会被过滤','不要只以动作分类证明码本通用，必须测试连续运动和跨佩戴'],experiments:['E1：连续 MAE、AEMG 离散、连续+离散双路，在同数据/参数下比较','E2：码本 256/1024/4096/8192，报告 perplexity、死码、量化误差和域互信息','E3：固定窗、能量窗、变化点窗、多尺度窗，比较手势与连续运动','E4：跨人/日/设备/旋转/位移 + 5% 少样本，附 token—运动学邻域分析'],visibleText:'AEMG 应成为本项目最重要的直接对照。建议复现其 contraction tokenizer 和 8,192 码本，再提出双路改进：离散分支学习可组合动作 motif，连续分支保留幅值、速度和细相位；联合以 masked token、teacher latent 对齐和未来运动学辅助损失训练。论文创新点可落在“连续与离散统一、圆环几何鲁棒、手势与连续运动双验证”。只有在相同数据和算力下同时超过 AEMG 分类、MOMENT 连续掩蔽及监督 emg2pose 基线，才能形成有说服力的顶会证据链。同时需要展示 codebook 利用率、跨日 token 稳定性与连续轨迹保真，排除分类标签空间带来的伪通用性。'}
    }
  }
];

